const appearanceData={
 irene:{name:'Irene Vale',role:'Language Curator',badge:'Case briefing',quote:'“Before you question the dead, learn to question the words they left behind.”',context:'Irene opens the sealed case file and marks three expressions in violet ink. She warns you that someone has rewritten not only the victim’s records, but the language used to describe the crime.',ru:'«Прежде чем задавать вопросы мёртвым, научитесь сомневаться в словах, которые они оставили». Irene открывает запечатанное дело и предупреждает: кто-то переписал не только записи о погибшей, но и сам язык расследования.',vocab:['sealed file — запечатанное дело','rewrite — переписывать','leave behind — оставлять после себя'],cls:'irene-scene',img:'irene',button:{A1:'Начать осмотр',A2:'Begin inspection',B1:'Begin inspection'}},
 morwen:{name:'Lady Morwen',role:'Minister of Memory',badge:'Ministry transmission',quote:'“This case is no longer under your authority. Record the death. Seal the apartment. Forget the woman.”',context:'A violet Ministry seal ignites above the mirror. Lady Morwen appears through the projection and orders you to close the investigation before the evidence can enter the public record.',ru:'«Это дело больше не находится в вашей юрисдикции. Зафиксируйте смерть. Опечатайте квартиру. Забудьте эту женщину». Леди Морвен требует прекратить расследование до того, как улики попадут в официальные записи.',vocab:['authority — полномочия','seal — опечатать','public record — официальная запись'],cls:'morwen-scene',img:'morwen',button:{A1:'Продолжить расследование',A2:'Continue the investigation',B1:'Continue the investigation'}},
 oren:{name:'Oren Thale',role:'Memory Physician',badge:'Encrypted medical message',quote:'“That ampoule was not made to erase a memory. It was made to preserve one inside a living body.”',context:'The empty Ministry ampoule releases a green pulse. A hidden medical signature identifies Oren Thale, a physician whose treatments can restore memories—or create convincing replacements.',ru:'«Эта ампула была создана не для стирания воспоминания. Она должна была сохранить его внутри живого тела». Скрытая медицинская подпись принадлежит Орену Тейлу — врачу, способному восстановить память или создать убедительную подмену.',vocab:['preserve — сохранять','living body — живое тело','replacement — замена'],cls:'oren-scene',img:'oren',button:{A1:'Вернуться к уликам',A2:'Return to the clues',B1:'Return to the clues'}},
 silas:{name:'Silas Vane',role:'Former Royal Investigator',badge:'Witness arrival',quote:'“You are looking for a dead woman. I am here because she was looking for you.”',context:'The apartment door opens without a sound. Silas Vane enters in a rain-soaked coat and places an old royal badge beside the mirror. He knows the victim’s name—and the name you had before the Archive.',ru:'«Вы ищете погибшую женщину. Я пришёл потому, что она искала вас». Сайлас Вейн входит в квартиру и кладёт рядом с зеркалом старый королевский жетон. Он знает имя погибшей — и имя, которое было у вас до Архива.',vocab:['be looking for — искать','rain-soaked — промокший под дождём','badge — жетон'],cls:'silas-scene',img:'silas',button:{A1:'Начать допрос',A2:'Begin the interrogation',B1:'Begin the interrogation'}},
 queen:{name:'The Nameless Queen',role:'Mirror Sovereign',badge:'Memory fracture',quote:'“They did not save your city. They taught it to remember the wrong life.”',context:'The interrogation room disappears from the mirror. A crowned figure watches from behind fractured glass. Her face changes every time you blink, but her voice remains inside your own memory.',ru:'«Они не спасли ваш город. Они научили его помнить неправильную жизнь». Комната для допросов исчезает в зеркале. За разбитым стеклом появляется коронованная фигура, чьё лицо меняется каждый раз, когда вы моргаете.',vocab:['fractured glass — разбитое стекло','the wrong life — неправильная жизнь','remain — оставаться'],cls:'queen-scene',img:'queen',button:{A1:'Сформировать отчёт',A2:'Write the report',B1:'Write the report'}},
 kael:{name:'Kael Dusk',role:'Shadow Hunter',badge:'Post-credits / Next case',quote:'“The thing beneath Evervale has started moving again. And this time, it remembers your scent.”',context:'Beyond the city walls, Kael Dusk finds fresh tracks around a sealed stone gate. The marks do not lead into the forest. They lead upward—toward Evervale.',ru:'«То, что находится под Эвервейлом, снова пришло в движение. И теперь оно помнит ваш запах». За городскими стенами Каэль Даск находит свежие следы у запечатанных каменных ворот. Они ведут не в лес, а к самому городу.',vocab:['beneath — под','fresh tracks — свежие следы','sealed gate — запечатанные ворота'],cls:'kael-scene',img:'kael',button:{A1:'Вернуться к финалу',A2:'Return to the ending',B1:'Return to the ending'}}
};
function showAppearance(key,next){appearanceKey=key;appearanceNext=next||'investigation';const d=appearanceData[key];const art=document.getElementById('appearanceArt');art.className='appearance-art img-'+d.img;const copy=document.getElementById('appearanceCopy');copy.className='appearance-copy '+d.cls;document.getElementById('appearanceBadge').textContent=d.badge;document.getElementById('appearanceName').textContent=d.name;document.getElementById('appearanceRole').textContent=d.role;document.getElementById('appearanceQuote').textContent=d.quote;document.getElementById('appearanceContext').textContent=d.context;const tr=document.getElementById('appearanceTranslation');tr.textContent=d.ru;tr.classList.toggle('hidden',(state.level!=='A1'&&state.level!=='A0'));const tb=document.getElementById('appearanceTranslateBtn');tb.classList.toggle('hidden',state.level!=='A2');document.getElementById('appearanceVocab').innerHTML=(isEnglishLevel(state.level)?[]:d.vocab).map(v=>'<span>'+v+'</span>').join('');document.getElementById('appearanceContinueBtn').textContent=d.button[state.level]||d.button[{A0:'A1',B2:'B1',C1:'B1'}[state.level]]||d.button.A2;go('appearance')}
function continueAppearance(){clickSfx();go(appearanceNext)}
function showPostCredits(){if(state.kaelSeen){go('start');return}state.kaelSeen=true;save();showAppearance('kael','ending')}

function normaliseState(s){s={...initial,...(s||{})};s.alignment={...initial.alignment,...(s.alignment||{})};s.bonds={...initial.bonds,...(s.bonds||{})};s.campaignHistory=Array.isArray(s.campaignHistory)?s.campaignHistory:[];s.secrets=Array.isArray(s.secrets)?s.secrets:[];s.hiddenFound=Array.isArray(s.hiddenFound)?s.hiddenFound:[];return s}let volatileSave=null;function save(){try{volatileSave=JSON.stringify(state);localStorage.setItem('evervale-v11',volatileSave)}catch(e){volatileSave=JSON.stringify(state)}}
function isEnglishLevel(level){return ['B1','B2','C1'].includes(level)}

function load(){try{const raw=localStorage.getItem('evervale-v11')||localStorage.getItem('evervale-v10')||localStorage.getItem('evervale-v9')||localStorage.getItem('evervale-v8');return raw?JSON.parse(raw):null}catch(e){try{return volatileSave?JSON.parse(volatileSave):null}catch(_){return null}}}
function go(id){document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));const target=document.getElementById(id);if(!target)return;target.classList.add('active');if(id==='analysisboard')renderAnalysisBoard();if(id==='hiddenstudy')renderHiddenStudy();if(id==='caretaker')renderCaretaker();if(id==='longcase')renderLongCase();if(id==='memory'&&state.memoryStage===0)setupWords();if(id==='memorytrace')renderMemoryTrace();if(id==='interrogation')renderQuestion();if(id==='verdict')renderVerdict();if(id==='campaign')renderCampaign();window.scrollTo(0,0);save()}
function openCodex(from){codexBack=from||'intro';go('codex')}
function closeCodex(){go(codexBack||'intro')}
function selectLevel(level){state=normaliseState({...initial,level,protagonist:state.protagonist||'female',music:state.music});save();go('character');if(state.music)startMusic()}
function continueGame(){const s=load();if(!s||!s.level){go('level');return}state=normaliseState(s);if(!state.protagonist){go('character');return}applyLanguage();renderProtagonist();if(state.music)startMusic();if(state.campaignNode){go('campaign');return}if(state.question>=dialogue.length){go('verdict');return}if(state.deepMemoryDone){go('interrogation');return}if(state.memoryTraceStep>0||state.memoryStage===1){go('memorytrace');return}if(state.longCaseDone){go('memory');return}if(state.longCaseStep>0||state.caretakerStep>=caretakerDialogue.length){go('longcase');return}if(state.hiddenFound.length===4){go('caretaker');return}if(state.analysisStep>=analysisQuestions.length){go('hiddenstudy');return}if(state.found.length===4){go('analysisboard');return}go('investigation')}
function restart(){const m=state.music;state=normaliseState({...initial,music:m});save();document.getElementById('levelIndicator').classList.add('hidden');go('level')}
function selectCharacter(p){state.protagonist=p;save();applyLanguage();renderProtagonist();go('intro');if(state.music)startMusic()}
function renderProtagonist(){const p=state.protagonist||'female';const titleMap={female: isEnglishLevel(state.level) ? 'Elara Vane · Archivist Investigator' : 'Элара Вейн · архивист-исследователь', male: isEnglishLevel(state.level) ? 'Arden Vane · Archivist Investigator' : 'Арден Вейн · архивист-исследователь'};['chooseFemale','chooseMale'].forEach(id=>{const el=document.getElementById(id);if(el)el.classList.remove('selected')});const selected=document.getElementById(p==='female'?'chooseFemale':'chooseMale');if(selected)selected.classList.add('selected');['introPortrait','introMini','investMini','dialogueMini'].forEach(id=>{const el=document.getElementById(id);if(el){el.classList.remove('female','male');el.classList.add(p)}});['investProfileName','dialogueProfileName','introProfileLabel'].forEach(id=>{const el=document.getElementById(id);if(el)el.textContent=titleMap[p]})}
function t(){return UI[state.level]||UI.A1}
function applyLanguage(){const u=t();document.documentElement.lang=isEnglishLevel(state.level)?'en':'ru';const map={brand1:u.brand,labelEvidence:u.evidence,labelStability:u.stability,labelInfluence:u.influence,musicBtn1:u.music,introKicker:u.introK,introTitle:u.introT,introP1:u.intro1,introP2:u.intro2,introBtn:u.introB,investKicker:u.investK,investTitle:u.investT,investProgress:u.progress,sceneTime:u.time,sceneDescription:u.scene,sceneTranslation:u.sceneRu,caseMaterials:u.materials,caseLead:u.lead,memoryBtn:u.memory,memoryBrand:u.memoryBrand,memoryKicker:u.memoryK,sentence:u.sentence,resetBtn:u.reset,memoryHintBtn:u.memoryHint,memoryStability:u.stability,musicBtn2:u.music,interrogationBrand:u.brand,labelTrust:u.trust,labelInfluence2:u.influence,musicBtn3:u.music,witnessLabel:u.witness,silasRole:u.role,verdictBrand:u.verdictBrand,trustFinalLabel:u.trust,verdictKicker:u.verdictK,verdictTitle:u.verdictT,verdictContext:u.verdictC,musicBtn4:u.music,endingKicker:u.endK,restartBtn:u.restart,menuBtn:u.menu,ireneRole:u.ireneRole,codexBtnIntro:isEnglishLevel(state.level)?'Character Codex':'Кодекс героев',codexBtnInvest:isEnglishLevel(state.level)?'Character Codex':'Кодекс героев',postCreditsBtn:isEnglishLevel(state.level)?'Post-credits / Next case':'Сцена после титров'};Object.entries(map).forEach(([id,v])=>{const e=document.getElementById(id);if(e)e.textContent=v});document.getElementById('levelIndicator').textContent='ENGLISH MODE · '+state.level+(isEnglishLevel(state.level)?'+':'');document.getElementById('levelIndicator').classList.add('hidden');document.getElementById('sceneTranslation').classList.toggle('hidden',(state.level!=='A1'&&state.level!=='A0'));document.getElementById('memoryHintBtn').classList.toggle('hidden',isEnglishLevel(state.level));renderEvidence();updateUI();renderProtagonist();updateMusicButtons()}
function renderEvidence(){const box=document.getElementById('evidenceList');box.innerHTML='';clues.forEach((c,i)=>{const found=state.found.includes(i+1);let extra='';if((state.level==='A1'||state.level==='A0'))extra=`<small class="translation">${c.ru}</small><small>${c.words}</small>`;else if(state.level==='A2')extra=`<small class="translation hidden" id="clueRu${i}">${c.ru}</small>`;box.innerHTML+=`<div class="evidence ${found?'':'locked'}" id="e${i+1}"><div class="num">0${i+1}</div><div><b>${c.en}</b><small>${c.desc}</small>${extra}</div></div>`});const tools=document.getElementById('investTools');tools.innerHTML='';if(state.level==='A2')tools.innerHTML=`<button class="tool-btn" onclick="toggleClueTranslations()">Show / hide clue translations</button><button class="tool-btn" onclick="showInvestHint()">Vocabulary hint</button>`;if((state.level==='A1'||state.level==='A0'))document.getElementById('investHint').textContent='Подсказка: осматривайте зеркало, стол, ковёр и область у окна.'}
function toggleClueTranslations(){document.querySelectorAll('[id^=clueRu]').forEach(e=>e.classList.toggle('hidden'))}function showInvestHint(){const h=document.getElementById('investHint');h.textContent='wardrobe — шкаф · evidence — улика · trace — след · reflection — отражение';h.classList.toggle('hidden')}
function findEvidence(n){clickSfx();if(state.found.includes(n))return;state.found.push(n);const msg=isEnglishLevel(state.level)?['The thread carries your Archive cipher.','The mirror whispers the name “Elara”.','The letter opens at the phrase: “The city died before.”','The ampoule predates your official birth.'][n-1]:['На нити обнаружен ваш архивный шифр.','Зеркало произносит имя: «Элара».','Письмо открывается на фразе: “The city died before.”','Ампула изготовлена раньше вашей официальной даты рождения.'][n-1];toast(msg);renderEvidence();updateUI();save();if(state.found.length===2&&!state.morwenSeen){state.morwenSeen=true;save();setTimeout(()=>showAppearance('morwen','investigation'),700);return}if(state.found.length===4&&!state.orenSeen){state.orenSeen=true;save();setTimeout(()=>showAppearance('oren','investigation'),700);return}if(state.found.length===4)showIrene(isEnglishLevel(state.level)?'All four clues are connected by one idea: the victim knew a version of you that the Archive officially denies.':'Все четыре улики связаны одной идеей: погибшая знала версию вас, существование которой Архив отрицает.')}

function renderAnalysisBoard(){
 const q=analysisQuestions[state.analysisStep];if(!q){go('hiddenstudy');return}
 const a1=(state.level==='A1'||state.level==='A0'),b1=isEnglishLevel(state.level);
 document.getElementById('analysisScore').textContent=state.analysisScore+'/4';document.getElementById('analysisStability').textContent=state.stability;document.getElementById('analysisProgress').textContent=(state.analysisStep+1)+' / '+analysisQuestions.length;
 document.getElementById('analysisTitle').textContent=b1?'Build the Timeline':'Постройте временную линию';document.getElementById('analysisIntro').textContent=b1?'Connect the physical evidence before entering the victim’s memory. A wrong conclusion may make the later reconstruction less stable.':'Свяжите вещественные улики до погружения в память погибшей. Ошибочный вывод сделает последующую реконструкцию менее стабильной.';
 document.getElementById('analysisQuestion').textContent=b1?q.q:q.qRu;document.getElementById('analysisContext').textContent=b1?q.context:q.contextRu;
 const tr=document.getElementById('analysisTranslation');tr.textContent=q.qRu+'\n'+q.contextRu;tr.classList.toggle('hidden',!a1);
 const tools=document.getElementById('analysisTools');tools.innerHTML='';if(state.level==='A2')tools.innerHTML='<button class="tool-btn" onclick="toggleBox(\'analysisTranslation\')">Show translation</button>';
 const box=document.getElementById('analysisOptions');box.innerHTML='';q.options.forEach((o,i)=>{const btn=document.createElement('button');btn.className='analysis-option';btn.innerHTML=o[0]+(a1?'<span class="ru">'+o[1]+'</span>':'');btn.onclick=()=>answerAnalysis(o[2],q.feedback);box.appendChild(btn)});updateMusicButtons();
}
function answerAnalysis(correct,feedback){clickSfx();if(correct){state.analysisScore++;toast(isEnglishLevel(state.level)?'Deduction confirmed':'Вывод подтверждён')}else{state.stability=Math.max(45,state.stability-4);toast(isEnglishLevel(state.level)?'The evidence does not support that conclusion':'Улики не подтверждают этот вывод')}state.analysisStep++;save();showIrene(isEnglishLevel(state.level)?feedback:'Комментарий: '+feedback);setTimeout(()=>{closeIrene();state.analysisStep>=analysisQuestions.length?go('hiddenstudy'):renderAnalysisBoard()},1100)}
function renderHiddenStudy(){const a1=(state.level==='A1'||state.level==='A0'),b1=isEnglishLevel(state.level);document.getElementById('hiddenEvidenceLabel').textContent=b1?'Hidden clues':'Скрытые улики';document.getElementById('hiddenEvidenceStat').textContent=state.hiddenFound.length+'/4';document.getElementById('hiddenStability').textContent=state.stability;document.getElementById('studyTitle').textContent=b1?'The Room Behind the Wall':'Комната за стеной';document.getElementById('studyIntro').textContent=b1?'Your deductions activate a concealed mechanism in the mirror frame. A second room opens behind the apartment wall.':'Ваши выводы активируют скрытый механизм в раме зеркала. За стеной квартиры открывается вторая комната.';document.getElementById('studyDescription').textContent=b1?'The annex contains objects collected across several versions of the same crime scene. Dust lies everywhere except on the chair facing the mirror.':'В тайной комнате хранятся предметы из нескольких версий одного места преступления. Пыль лежит везде, кроме стула напротив зеркала.';document.getElementById('studyMaterials').textContent=b1?'Recovered material':'Найденные материалы';document.getElementById('studyLead').textContent=b1?'Find four objects that explain why Apartment 17 appears in several buildings.':'Найдите четыре предмета, объясняющих, почему квартира №17 отмечена в нескольких зданиях.';document.getElementById('studyProgress').textContent=b1?'Find four hidden clues':'Найдите четыре скрытые улики';document.getElementById('caretakerBtn').textContent=b1?'Question the caretaker':'Допросить смотрительницу';document.getElementById('caretakerBtn').disabled=state.hiddenFound.length<4;
 const box=document.getElementById('hiddenEvidenceList');box.innerHTML='';hiddenClues.forEach((c,i)=>{const found=state.hiddenFound.includes(i+1);let extra='';if(a1)extra='<small class="translation">'+c.ru+'</small><small>'+c.words+'</small>';else if(state.level==='A2')extra='<small class="translation hidden" id="hiddenRu'+i+'">'+c.ru+'</small>';box.innerHTML+='<div class="study-clue '+(found?'':'locked')+'"><div class="sig">0'+(i+1)+'</div><div><b>'+c.en+'</b><small>'+c.desc+'</small>'+extra+'</div></div>'});
 const tools=document.getElementById('studyTools');tools.innerHTML='';if(state.level==='A2')tools.innerHTML='<button class="tool-btn" onclick="toggleHiddenTranslations()">Show / hide translations</button>';if(a1){document.getElementById('studyHint').textContent='Подсказка: осмотрите полку слева, верхнюю часть стены, стол и область возле стула.';document.getElementById('studyHint').classList.remove('hidden')}else document.getElementById('studyHint').classList.add('hidden');
 for(let i=1;i<=4;i++){const h=document.getElementById('sh'+i);if(h){const f=state.hiddenFound.includes(i);h.classList.toggle('found',f);if(f)h.textContent='✓'}}updateMusicButtons();
}
function findHiddenEvidence(n){clickSfx();if(state.hiddenFound.includes(n))return;state.hiddenFound.push(n);const msg=isEnglishLevel(state.level)?['The recording uses your voice.','Seventeen locations share the same apartment number.','The photograph was taken before your registered birth.','Mara Holt’s voiceprint is sealed inside.'][n-1]:['В записи звучит ваш голос.','Один номер квартиры связан с семнадцатью адресами.','Фотография сделана до вашего официального рождения.','В печати обнаружен голосовой след Мары Холт.'][n-1];toast(msg);save();renderHiddenStudy();if(state.hiddenFound.length===4)showIrene(isEnglishLevel(state.level)?'The hidden room turns the crime scene into a network. Mara Holt is no longer only a caretaker; she is connected to the memory seals.':'Тайная комната превращает место преступления в целую сеть. Мара Холт связана с печатями памяти и должна быть допрошена.')}
function toggleHiddenTranslations(){hiddenClues.forEach((_,i)=>{const e=document.getElementById('hiddenRu'+i);if(e)e.classList.toggle('hidden')})}
function renderCaretaker(){if(state.caretakerStep>=caretakerDialogue.length){save();go('longcase');return}const q=caretakerDialogue[state.caretakerStep],a1=(state.level==='A1'||state.level==='A0'),b1=isEnglishLevel(state.level);document.getElementById('caretakerTrustStat').textContent=state.caretakerTrust;document.getElementById('caretakerInfluence').textContent=state.influence;document.getElementById('caretakerProgress').textContent=(b1?'Question ':'Вопрос ')+(state.caretakerStep+1)+' / '+caretakerDialogue.length;document.getElementById('caretakerRole').textContent=b1?'Caretaker of the Upper District residence':'Смотрительница дома в Верхнем квартале';document.getElementById('caretakerContext').textContent=a1?q.contextRu:q.context;document.getElementById('caretakerSpeech').textContent='“'+q.speech+'”';const tr=document.getElementById('caretakerTranslation');tr.textContent=q.ru;tr.classList.toggle('hidden',!a1);const vocab=document.getElementById('caretakerVocab');vocab.innerHTML=q.vocab.map(v=>'<span>'+v+'</span>').join('');vocab.classList.toggle('hidden',!a1);const tools=document.getElementById('caretakerTools');tools.innerHTML='';if(state.level==='A2')tools.innerHTML='<button class="tool-btn" onclick="toggleBox(\'caretakerTranslation\')">Show translation</button><button class="tool-btn" onclick="toggleBox(\'caretakerVocab\')">Vocabulary</button>';const choices=document.getElementById('caretakerChoices');choices.innerHTML='';q.choices.forEach(c=>{const btn=document.createElement('button');btn.className='choice';btn.innerHTML='<small>'+c.tone+'</small>'+c.en+(a1?'<span class="ru">'+c.ru+'</span>':'');btn.onclick=()=>answerCaretaker(c);choices.appendChild(btn)});updateMusicButtons()}
function answerCaretaker(c){clickSfx();state.caretakerTrust+=c.trust;state.influence+=c.influence;state.caretakerStep++;save();showIrene(isEnglishLevel(state.level)?c.fb:'Комментарий: '+c.fb);setTimeout(()=>{closeIrene();renderCaretaker()},1100)}
function renderMemoryTrace(){if(state.memoryTraceStep>=memoryTraceQuestions.length){state.deepMemoryDone=true;save();if(!state.silasSeen){state.silasSeen=true;showAppearance('silas','interrogation')}else go('interrogation');return}const q=memoryTraceQuestions[state.memoryTraceStep],a1=(state.level==='A1'||state.level==='A0'),b1=isEnglishLevel(state.level);document.getElementById('memoryTraceProgress').textContent=(state.memoryTraceStep+1)+'/'+memoryTraceQuestions.length;document.getElementById('memoryTraceStability').textContent=state.stability;document.getElementById('memoryTraceTitle').textContent=b1?q.title:q.titleRu;document.getElementById('memoryTraceContext').textContent=b1?q.context:q.contextRu;document.getElementById('memoryFragment').textContent='“'+q.fragment+'”';const tr=document.getElementById('memoryTraceTranslation');tr.textContent=q.fragmentRu+'\n\n'+q.contextRu;tr.classList.toggle('hidden',!a1);const tools=document.getElementById('memoryTraceTools');tools.innerHTML='';if(state.level==='A2')tools.innerHTML='<button class="tool-btn" onclick="toggleBox(\'memoryTraceTranslation\')">Show translation</button>';const box=document.getElementById('memoryTraceOptions');box.innerHTML='';q.options.forEach(o=>{const btn=document.createElement('button');btn.className='memory-trace-option';btn.innerHTML=o[0]+(a1?'<span class="ru" style="display:block;margin-top:7px;color:#bcb4bd">'+o[1]+'</span>':'');btn.onclick=()=>answerMemoryTrace(o[2],q.feedback);box.appendChild(btn)});updateMusicButtons()}
function answerMemoryTrace(correct,feedback){clickSfx();if(!correct){state.stability=Math.max(40,state.stability-4);toast(isEnglishLevel(state.level)?'The fragment destabilises':'Фрагмент становится нестабильным')}else toast(isEnglishLevel(state.level)?'Memory fragment verified':'Фрагмент памяти подтверждён');state.memoryTraceStep++;save();showIrene(isEnglishLevel(state.level)?feedback:'Комментарий: '+feedback);setTimeout(()=>{closeIrene();renderMemoryTrace()},1100)}

function setupWords(){const words=['The','city','did','not','survive','—','it','was','rewritten'];state.words=[];const b=document.getElementById('wordbank');b.innerHTML='';[...words].sort(()=>Math.random()-.5).forEach(w=>{const x=document.createElement('button');x.className='word';x.textContent=w;x.onclick=()=>chooseWord(w,x);b.appendChild(x)});document.getElementById('sentence').textContent=t().sentence;document.getElementById('memoryTranslation').textContent=isEnglishLevel(state.level)?'':(state.level==='A1'||state.level==='A0')?'Город не выжил — его переписали. Подсказка: did not + глагол; was + V3.':'Translation: Город не выжил — его переписали.';document.getElementById('memoryTranslation').classList.toggle('hidden',(state.level!=='A1'&&state.level!=='A0'))}
function resetWords(){setupWords();clickSfx()}function chooseWord(w,e){clickSfx(840,.02,.05);state.words.push(w);e.classList.add('used');const current=state.words.join(' '),target='The city did not survive — it was rewritten';document.getElementById('sentence').textContent=current;if(!target.startsWith(current)){state.stability=Math.max(55,state.stability-5);updateUI();showIrene(isEnglishLevel(state.level)?'The word order is incorrect. Remember the passive pattern: subject + was + past participle.':'Порядок слов неверный. В пассивной конструкции используйте: подлежащее + was + третья форма глагола.');setTimeout(setupWords,900)}else if(current===target){state.stability=Math.max(55,state.stability-8);updateUI();showIrene(isEnglishLevel(state.level)?'The sentence is complete. The passive voice deliberately hides who rewrote the city.':'Фраза восстановлена. Пассивный залог намеренно скрывает того, кто переписал город.');state.memoryStage=1;save();setTimeout(()=>go('memorytrace'),1250)}}
function renderQuestion(){if(state.question>=dialogue.length){if(!state.queenSeen){state.queenSeen=true;save();showAppearance('queen','verdict')}else go('verdict');return}const q=dialogue[state.question];document.getElementById('questionProgress').textContent=`${t().q} ${state.question+1} ${t().of} ${dialogue.length}`;document.getElementById('speech').textContent='“'+q.speech+'”';document.getElementById('context').textContent=(state.level==='A1'||state.level==='A0')?q.contextRu:q.context;const tr=document.getElementById('speechTranslation');tr.textContent=q.ru;tr.classList.toggle('hidden',(state.level!=='A1'&&state.level!=='A0'));const vocab=document.getElementById('vocab');vocab.innerHTML=q.vocab.map(v=>`<span>${v}</span>`).join('');vocab.classList.toggle('hidden',(state.level!=='A1'&&state.level!=='A0'));const tools=document.getElementById('dialogueTools');tools.innerHTML='';if(state.level==='A2')tools.innerHTML='<button class="tool-btn" onclick="toggleBox(\'speechTranslation\')">Show translation</button><button class="tool-btn" onclick="toggleBox(\'vocab\')">Vocabulary</button>';const choices=document.getElementById('choices');choices.innerHTML='';q.choices.forEach(c=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`<small>${c.tone}</small>${c.en}${(state.level==='A1'||state.level==='A0')?`<span class="ru">${c.ru}</span>`:''}`;b.onclick=()=>answer(c);choices.appendChild(b)});updateUI()}
function answer(c){clickSfx();state.trust+=c.trust;state.influence+=c.influence;state.question++;updateUI();save();showIrene(isEnglishLevel(state.level)?c.fbEn:c.fbRu+(state.level==='A2'?' '+c.fbEn:''));setTimeout(renderQuestion,1250)}
function renderVerdict(){document.getElementById('trustFinal').textContent=state.trust;document.getElementById('evidenceFinal').textContent=(state.level==='A1'||state.level==='A0')?'Материалы дела 52/52':'Case materials 52/52';const box=document.getElementById('verdictChoices');box.innerHTML='';verdicts[state.level].forEach(v=>{box.innerHTML+=`<button class="verdict" onclick="finish('${v[3]}')"><div class="tag">${v[0]}</div><h3>${v[1]}</h3><p>${v[2]}</p></button>`})}

const longCaseSegments=[{"k":"FORENSIC ANNEX","kRu":"СУДЕБНАЯ ЛАБОРАТОРИЯ","title":"Forensic examination","titleRu":"Судебная экспертиза","desc":"The body, the ampoule, and the silver thread are examined independently. Every result contradicts the official timeline.","descRu":"Тело, ампула и серебряная нить исследуются независимо. Каждый результат противоречит официальной хронологии.","symbol":"⚗"},{"k":"BUILDING SWEEP","kRu":"ПОВТОРНЫЙ ОСМОТР ДОМА","title":"The residence remembers","titleRu":"Дом хранит следы","desc":"You return to the building and inspect spaces the first search team ignored: service corridors, roof access, neighbouring rooms, and the old speaking pipes.","descRu":"Вы возвращаетесь в дом и осматриваете места, которые пропустила первая группа: служебные коридоры, крышу, соседние квартиры и старые переговорные трубы.","symbol":"⌂"},{"k":"SEALED REGISTRY","kRu":"ЗАПЕЧАТАННЫЙ РЕЕСТР","title":"Paper identities","titleRu":"Бумажные личности","desc":"Official documents reveal that the apartment, the victim, and even your own identity have been repeatedly reassigned.","descRu":"Официальные документы показывают, что квартира, погибшая и даже ваша собственная личность неоднократно переназначались.","symbol":"▤"},{"k":"WITNESS CIRCUIT","kRu":"КРУГ СВИДЕТЕЛЕЙ","title":"Six people, six versions","titleRu":"Шесть людей, шесть версий","desc":"A pharmacist, a neighbour, a courier, a night guard, a Ministry clerk, and a child remember incompatible versions of the same night.","descRu":"Фармацевт, соседка, курьер, ночной охранник, служащий Министерства и ребёнок помнят несовместимые версии одной ночи.","symbol":"◉"},{"k":"LANGUAGE CIPHER","kRu":"ЯЗЫКОВОЙ ШИФР","title":"Grammar as evidence","titleRu":"Грамматика как улика","desc":"Irene helps analyse tense, pronouns, passive constructions, and an acrostic hidden in the victim’s final messages.","descRu":"Irene помогает исследовать времена, местоимения, пассивные конструкции и акростих в последних сообщениях погибшей.","symbol":"A"},{"k":"OREN’S LAB","kRu":"ЛАБОРАТОРИЯ ОРЕНА","title":"The memory physician","titleRu":"Врач памяти","desc":"Oren Thale agrees to answer questions only while conducting tests on the sample taken from the victim. His answers may be more dangerous than his lies.","descRu":"Орен Тейл соглашается отвечать только во время анализа образца погибшей. Его ответы могут оказаться опаснее его лжи.","symbol":"✧"},{"k":"SUSPECT MATRIX","kRu":"МАТРИЦА ПОДОЗРЕВАЕМЫХ","title":"Motive, means, opportunity","titleRu":"Мотив, средство, возможность","desc":"The evidence is arranged against Morwen, Oren, Silas, the victim, and a previous version of you. More than one suspect may be telling the truth.","descRu":"Улики сопоставляются с Морвен, Ореном, Сайласом, погибшей и предыдущей версией вас. Правду могут говорить сразу несколько подозреваемых.","symbol":"◇"},{"k":"FINAL RECONSTRUCTION","kRu":"ФИНАЛЬНАЯ РЕКОНСТРУКЦИЯ","title":"The death that was designed","titleRu":"Спроектированная смерть","desc":"You reconstruct the final hour and discover that the crime scene was not created to hide a murder. It was created to force a particular investigator to remember.","descRu":"Вы восстанавливаете последний час и понимаете: место преступления создали не для сокрытия убийства. Его создали, чтобы заставить конкретного следователя вспомнить.","symbol":"∞"}];
const longCaseNodes=[{"seg":0,"loc":"Autopsy chamber · 03:40","title":"A Body Without Blood","titleRu":"Тело без крови","body":"The medical examiner finds no blood loss, no defensive wounds, and no ordinary cause of death. The skin is biologically alive, but the organs contain almost no personal memory residue. The body resembles a house from which every inhabitant has moved out.","bodyRu":"Судебный врач не обнаруживает кровопотери, защитных ран и обычной причины смерти. Кожа биологически жива, но органы почти не содержат следов личной памяти. Тело напоминает дом, из которого выехали все жильцы.","task":"Which conclusion is best supported by the examination?","taskRu":"Какой вывод лучше всего подтверждается экспертизой?","opts":[{"en":"The body was emptied of identity before death.","ru":"Личность была извлечена из тела до смерти.","tag":"ANALYSIS"},{"en":"The victim died from an invisible weapon.","ru":"Погибшая умерла от невидимого оружия.","tag":"ASSUMPTION"},{"en":"The examiner falsified every result.","ru":"Эксперт подделал все результаты.","tag":"DISTRACTION"}],"correct":0,"vocab":["residue — остаточный след","defensive wound — защитная рана","emptied of — освобождённый от"],"fact":1,"witness":0,"doc":0},{"seg":0,"loc":"Chemical bench · 04:05","title":"Three Compounds in One Ampoule","titleRu":"Три вещества в одной ампуле","body":"The ampoule contains a sedative, a memory stabiliser, and a compound used to preserve a consciousness outside the body for several hours. The mixture is expensive, unstable, and normally restricted to Ministry laboratories.","bodyRu":"В ампуле находятся успокоительное, стабилизатор памяти и вещество, позволяющее несколько часов сохранять сознание вне тела. Смесь дорогая, нестабильная и обычно доступна только лабораториям Министерства.","task":"What was the most likely purpose of the mixture?","taskRu":"Каково наиболее вероятное назначение смеси?","opts":[{"en":"To remove and temporarily store a living identity.","ru":"Извлечь и временно сохранить живую личность.","tag":"FORENSICS"},{"en":"To treat an ordinary fever.","ru":"Лечить обычную лихорадку.","tag":"MEDICINE"},{"en":"To destroy the body immediately.","ru":"Немедленно уничтожить тело.","tag":"POISON"}],"correct":0,"vocab":["sedative — успокоительное","stabiliser — стабилизатор","restricted — ограниченный"],"fact":1,"witness":0,"doc":0},{"seg":0,"loc":"Thread analysis · 04:30","title":"The Silver Thread Was Cut Twice","titleRu":"Серебряную нить перерезали дважды","body":"Microscopic marks show that the memory-thread was first cut cleanly with a Ministry instrument, then torn by hand several minutes later. Someone completed the procedure; someone else tried to interrupt it.","bodyRu":"Микроскопические следы показывают: нить памяти сначала аккуратно перерезали инструментом Министерства, а через несколько минут разорвали рукой. Кто-то завершил процедуру, а кто-то другой попытался её прервать.","task":"What does the double damage prove?","taskRu":"Что доказывают два разных повреждения?","opts":[{"en":"At least two people acted at different moments.","ru":"Как минимум два человека действовали в разное время.","tag":"TIMELINE"},{"en":"Silas alone performed the entire procedure.","ru":"Всю процедуру в одиночку провёл Сайлас.","tag":"CERTAINTY"},{"en":"The thread was never used.","ru":"Нить вообще не использовали.","tag":"ERROR"}],"correct":0,"vocab":["microscopic marks — микроследы","tear by hand — разорвать рукой","interrupt — прервать"],"fact":1,"witness":0,"doc":0},{"seg":0,"loc":"Chronometry desk · 04:55","title":"The Clock Remembers Two Midnights","titleRu":"Часы помнят две полуночи","body":"The stopped clock contains two overlapping mechanical memories: 23:59 and 02:17. The second time matches the moment the mirror reacted to your voice. The clock was not broken; its previous state was layered over the current one.","bodyRu":"Остановившиеся часы содержат две наложенные механические памяти: 23:59 и 02:17. Второе время совпадает с моментом, когда зеркало отреагировало на ваш голос. Часы не сломаны: их прежнее состояние наложили на настоящее.","task":"Why preserve two times in the same object?","taskRu":"Зачем сохранять в одном предмете два времени?","opts":[{"en":"To mark both the procedure and the arrival of the intended investigator.","ru":"Отметить и процедуру, и прибытие нужного следователя.","tag":"MESSAGE"},{"en":"Because the clockmaker made a mistake.","ru":"Потому что часовщик ошибся.","tag":"ACCIDENT"},{"en":"To prove the victim left the city.","ru":"Доказать, что погибшая покинула город.","tag":"ALIBI"}],"correct":0,"vocab":["overlapping — наложенный","intended investigator — нужный следователь","state — состояние"],"fact":1,"witness":0,"doc":0},{"seg":0,"loc":"Print chamber · 05:20","title":"Your Fingerprint Under Her Skin","titleRu":"Ваш отпечаток под её кожей","body":"A partial fingerprint is found beneath a healed layer of skin on the victim’s wrist. It belongs to you, but the tissue formed around it years ago. The mark could not have been planted during the current investigation.","bodyRu":"Под зажившим слоем кожи на запястье погибшей обнаружен ваш частичный отпечаток. Ткань сформировалась вокруг него много лет назад. Этот след невозможно было подделать во время нынешнего расследования.","task":"What is the strongest implication?","taskRu":"Какое следствие наиболее убедительно?","opts":[{"en":"You physically knew this body long before your official life began.","ru":"Вы физически знали это тело задолго до начала официальной жизни.","tag":"HISTORY"},{"en":"Someone copied your print tonight.","ru":"Сегодня ночью кто-то скопировал ваш отпечаток.","tag":"FRAME"},{"en":"The pattern only looks similar.","ru":"Узор лишь случайно похож.","tag":"COINCIDENCE"}],"correct":0,"vocab":["healed layer — заживший слой","implication — следствие","official life — официальная жизнь"],"fact":1,"witness":0,"doc":0},{"seg":1,"loc":"Service lift · 06:10","title":"The Lift Stops at Floor Seventeen","titleRu":"Лифт останавливается на семнадцатом этаже","body":"The building has only nine visible floors, yet the service lift contains a hidden seventeenth stop. When activated with the victim’s key, it opens onto a narrow corridor whose walls carry the same wallpaper as Apartment 17.","bodyRu":"В доме всего девять видимых этажей, однако служебный лифт содержит скрытую кнопку семнадцатого. Ключ погибшей открывает узкий коридор с теми же обоями, что и в квартире №17.","task":"What is the most reasonable interpretation?","taskRu":"Какое объяснение наиболее разумно?","opts":[{"en":"Apartment 17 is a repeating location, not a single room.","ru":"Квартира №17 — повторяющаяся локация, а не одна комната.","tag":"ARCHITECTURE"},{"en":"The lift number was painted incorrectly.","ru":"Номер лифта нарисовали неправильно.","tag":"MISTAKE"},{"en":"The entire building is imaginary.","ru":"Весь дом является воображаемым.","tag":"DREAM"}],"correct":0,"vocab":["visible floor — видимый этаж","repeating location — повторяющаяся локация","corridor — коридор"],"fact":1,"witness":0,"doc":0},{"seg":1,"loc":"Room 16 · 06:35","title":"A Tenant Erased Mid-Sentence","titleRu":"Жильца стёрли на середине фразы","body":"Room 16 contains a breakfast table set for two and a diary ending with the words: “The woman next door asked me to remember—”. Every official record says the room has been empty for twelve years.","bodyRu":"В квартире №16 накрыт завтрак на двоих, а дневник заканчивается словами: «Женщина из соседней квартиры попросила меня помнить—». Официально помещение пустует двенадцать лет.","task":"Which item should be treated as the primary evidence?","taskRu":"Что следует считать основной уликой?","opts":[{"en":"The unfinished diary entry linked to the victim.","ru":"Незаконченная запись, связанная с погибшей.","tag":"DOCUMENT"},{"en":"The colour of the tablecloth.","ru":"Цвет скатерти.","tag":"DECOR"},{"en":"The caretaker’s dislike of the tenant.","ru":"Неприязнь смотрительницы к жильцу.","tag":"RUMOUR"}],"correct":0,"vocab":["unfinished entry — незаконченная запись","primary evidence — основная улика","official record — официальная запись"],"fact":1,"witness":0,"doc":1},{"seg":1,"loc":"Room 18 · 07:00","title":"The Child Drew You Twice","titleRu":"Ребёнок нарисовал вас дважды","body":"A child’s drawing shows two versions of you standing on opposite sides of the victim. One wears your current Archive coat; the other wears an older uniform removed from service decades ago. The child labelled both figures with the same name.","bodyRu":"На детском рисунке две версии вас стоят по разные стороны от погибшей. Одна носит нынешнее пальто Архива, другая — форму, снятую с производства десятилетия назад. Обе фигуры подписаны одним именем.","task":"What does the drawing add to the case?","taskRu":"Что рисунок добавляет к делу?","opts":[{"en":"Independent evidence that more than one version of you existed.","ru":"Независимое подтверждение существования нескольких версий вас.","tag":"CORROBORATION"},{"en":"Absolute proof that you killed the victim.","ru":"Абсолютное доказательство вашей вины.","tag":"PROOF OF GUILT"},{"en":"Children’s drawings can never be evidence.","ru":"Детские рисунки никогда не могут быть уликами.","tag":"NOTHING"}],"correct":0,"vocab":["corroboration — подтверждение","opposite sides — по разные стороны","uniform — форма"],"fact":1,"witness":0,"doc":0},{"seg":1,"loc":"Roof access · 07:25","title":"Footprints That Begin in the Rain","titleRu":"Следы начинаются под дождём","body":"On the roof, wet footprints begin in the centre of an open space without approaching from any doorway. They lead to the chimney connected to Apartment 17’s speaking pipe. The pattern suggests a person arrived through a transferred memory rather than by physical movement.","bodyRu":"На крыше мокрые следы начинаются посреди открытого пространства, не приближаясь ни от одной двери. Они ведут к дымоходу, связанному с переговорной трубой квартиры №17. Похоже, человек появился через перенос памяти, а не обычным путём.","task":"Which hypothesis best fits the footprints?","taskRu":"Какая гипотеза лучше объясняет следы?","opts":[{"en":"A consciousness was projected into a prepared body on the roof.","ru":"Сознание перенесли в подготовленное тело на крыше.","tag":"TRANSFER"},{"en":"The suspect flew over the building.","ru":"Подозреваемый прилетел над домом.","tag":"FLIGHT"},{"en":"The rain created human footprints by itself.","ru":"Дождь сам создал человеческие следы.","tag":"WEATHER"}],"correct":0,"vocab":["projected — перенесённый","prepared body — подготовленное тело","approach — приближаться"],"fact":1,"witness":0,"doc":0},{"seg":1,"loc":"Boiler room · 07:50","title":"Pressure Rose Before the Murder","titleRu":"Давление поднялось до убийства","body":"The boiler log records a sudden pressure increase at 23:41, eighteen minutes before the staged time of death. The heating pipes pass directly behind the hidden study and can carry whispered sound through the building.","bodyRu":"Журнал котельной фиксирует резкий скачок давления в 23:41 — за восемнадцать минут до инсценированного времени смерти. Трубы проходят за тайным кабинетом и способны переносить шёпот по всему дому.","task":"Why is the pressure log important?","taskRu":"Почему важен журнал давления?","opts":[{"en":"It proves preparations began before the official death time.","ru":"Он доказывает, что подготовка началась до официального времени смерти.","tag":"TIMING"},{"en":"It proves the boiler killed the victim.","ru":"Он доказывает, что котёл убил погибшую.","tag":"CAUSE"},{"en":"Mechanical records cannot support a timeline.","ru":"Механические записи не помогают установить хронологию.","tag":"IRRELEVANT"}],"correct":0,"vocab":["pressure increase — скачок давления","staged time — инсценированное время","preparation — подготовка"],"fact":1,"witness":0,"doc":1},{"seg":2,"loc":"Civil Registry · 08:30","title":"A Death Certificate Filed Yesterday","titleRu":"Свидетельство о смерти подали вчера","body":"The victim’s death certificate was registered twenty-six hours before her body was found. The clerk’s signature is genuine, but the clerk remembers signing a blank page. The name field changes whenever you look away.","bodyRu":"Свидетельство о смерти зарегистрировали за двадцать шесть часов до обнаружения тела. Подпись служащего подлинная, но он помнит, что подписывал пустой лист. Поле имени меняется, когда вы отводите взгляд.","task":"What does the early certificate suggest?","taskRu":"На что указывает раннее свидетельство?","opts":[{"en":"The discovery of the body was scheduled in advance.","ru":"Обнаружение тела было запланировано заранее.","tag":"PLANNING"},{"en":"The clerk accidentally predicted the future.","ru":"Служащий случайно предсказал будущее.","tag":"ERROR"},{"en":"No crime occurred.","ru":"Преступления не было.","tag":"INNOCENCE"}],"correct":0,"vocab":["file a certificate — зарегистрировать свидетельство","blank page — пустой лист","scheduled — запланированный"],"fact":1,"witness":0,"doc":1},{"seg":2,"loc":"Property Ledger · 08:55","title":"Seventeen Tenants, One Handwriting","titleRu":"Семнадцать жильцов, один почерк","body":"The lease for Apartment 17 lists seventeen tenants across eighty years. Their names differ, but every signature was written by the same hand. The pressure and angle match the victim’s final letter.","bodyRu":"В договоре квартиры №17 указаны семнадцать жильцов за восемьдесят лет. Имена различаются, но все подписи сделаны одной рукой. Нажим и угол совпадают с последним письмом погибшей.","task":"Which conclusion is strongest?","taskRu":"Какой вывод наиболее убедителен?","opts":[{"en":"The victim repeatedly lived under different identities.","ru":"Погибшая неоднократно жила под разными личностями.","tag":"IDENTITY"},{"en":"A random landlord forged every lease for money.","ru":"Случайный хозяин подделал договоры ради денег.","tag":"FORGERY"},{"en":"All seventeen tenants had identical handwriting.","ru":"У всех семнадцати жильцов был одинаковый почерк.","tag":"COINCIDENCE"}],"correct":0,"vocab":["lease — договор аренды","handwriting — почерк","under an identity — под личностью"],"fact":1,"witness":0,"doc":1},{"seg":2,"loc":"Birth Archive · 09:20","title":"Your Birth Record Has Seven Layers","titleRu":"У вашей записи о рождении семь слоёв","body":"Chemical light reveals seven erased names beneath your current birth record. Each layer begins on a different date but uses the same witness: Silas Vane. The earliest layer predates his official career.","bodyRu":"Химический свет обнаруживает под вашей нынешней записью о рождении семь стёртых имён. У каждого слоя своя дата, но один свидетель — Сайлас Вейн. Самая ранняя запись старше его официальной карьеры.","task":"What must now be questioned?","taskRu":"Что теперь необходимо поставить под сомнение?","opts":[{"en":"Both your age and Silas’s official history.","ru":"Ваш возраст и официальную историю Сайласа.","tag":"IDENTITY"},{"en":"Only Silas’s handwriting.","ru":"Только почерк Сайласа.","tag":"ONLY SILAS"},{"en":"Birth records cannot be altered.","ru":"Записи о рождении невозможно изменить.","tag":"NOTHING"}],"correct":0,"vocab":["layer — слой","predate — предшествовать","official history — официальная история"],"fact":1,"witness":0,"doc":1},{"seg":2,"loc":"Budget Chamber · 09:45","title":"Project “Second History” Never Closed","titleRu":"Проект «Вторая история» не закрывали","body":"Budget lines continue for thirty years after the project’s official termination. Payments go to memory physicians, language curators, residential caretakers, and “anchor maintenance.” Your investigator number appears beside the anchor expenses.","bodyRu":"Финансирование продолжается тридцать лет после официального закрытия проекта. Деньги получают врачи памяти, кураторы языка, смотрители домов и служба «обслуживания якорей». Рядом с расходами на якоря стоит номер вашего следователя.","task":"What role does the budget imply for you?","taskRu":"Какую роль предполагает бюджет?","opts":[{"en":"You were maintained as part of the project, not merely assigned to investigate it.","ru":"Вас обслуживали как часть проекта, а не просто назначили расследовать его.","tag":"SUBJECT"},{"en":"You were only an accountant.","ru":"Вы были только бухгалтером.","tag":"AUDITOR"},{"en":"You had no connection to the project.","ru":"Вы не имели отношения к проекту.","tag":"OUTSIDER"}],"correct":0,"vocab":["budget line — статья бюджета","maintenance — обслуживание","assigned — назначенный"],"fact":1,"witness":0,"doc":1},{"seg":2,"loc":"Personnel Vault · 10:10","title":"Mara Holt Has a Missing Decade","titleRu":"У Мары Холт отсутствует десять лет","body":"Mara’s personnel file jumps from age twenty-nine to age thirty-nine without any recorded employment. A sealed note states: “Caretaker retained after witnessing Anchor Nine’s first collapse.”","bodyRu":"Личное дело Мары перескакивает с двадцати девяти до тридцати девяти лет без записей о работе. В закрытой заметке сказано: «Смотрительница сохранена после первого распада Якоря Девять».","task":"Why was Mara probably kept in the building?","taskRu":"Почему Мару, вероятно, оставили в доме?","opts":[{"en":"She remembered an earlier failure of your identity.","ru":"Она помнила прежний распад вашей личности.","tag":"WITNESS"},{"en":"She was uniquely good at cleaning mirrors.","ru":"Она особенно хорошо чистила зеркала.","tag":"CLEANING"},{"en":"She was imprisoned for theft.","ru":"Её заключили за кражу.","tag":"PUNISHMENT"}],"correct":0,"vocab":["retained — сохранённый на должности","collapse — распад","personnel file — личное дело"],"fact":1,"witness":1,"doc":1},{"seg":3,"loc":"Apothecary Lane · 10:50","title":"Elian Ross Sold Two Identical Orders","titleRu":"Элиан Росс продал два одинаковых заказа","body":"The pharmacist remembers the victim buying the Ministry mixture at dusk. An hour later, a second customer with your face purchased the same ingredients and asked how long a transferred identity could survive without a body.","bodyRu":"Фармацевт помнит, как погибшая купила смесь Министерства на закате. Через час второй покупатель с вашим лицом приобрёл те же вещества и спросил, сколько перенесённая личность может существовать без тела.","task":"Which detail should be challenged first?","taskRu":"Какую деталь следует проверить первой?","opts":[{"en":"Whether the second customer was you or another version wearing your face.","ru":"Были ли вторым покупателем вы или другая версия с вашим лицом.","tag":"IDENTIFICATION"},{"en":"Whether the ingredients were expensive.","ru":"Дорого ли стоили вещества.","tag":"PRICE"},{"en":"Whether it was raining outside.","ru":"Шёл ли снаружи дождь.","tag":"WEATHER"}],"correct":0,"vocab":["transferred identity — перенесённая личность","recognise — узнавать","ingredient — вещество"],"fact":1,"witness":1,"doc":0},{"seg":3,"loc":"Neighbour’s parlour · 11:20","title":"Vera Noll Heard an Argument in Your Voice","titleRu":"Вера Нолл слышала спор вашим голосом","body":"Vera heard two people arguing in Apartment 17. Both voices sounded like yours, but one spoke formal Archive English while the other used an obsolete dialect from old Evervale.","bodyRu":"Вера слышала спор двух людей в квартире №17. Оба голоса звучали как ваш, но один говорил на официальном английском Архива, а другой — на устаревшем диалекте старого Эвервейла.","task":"What does the language difference establish?","taskRu":"Что доказывает языковое различие?","opts":[{"en":"The speakers shared a voice but came from different identity histories.","ru":"Говорящие имели один голос, но разные истории личности.","tag":"SEPARATE VERSIONS"},{"en":"One person was certainly performing both roles.","ru":"Один человек точно разыгрывал обе роли.","tag":"ACTING"},{"en":"The pipes distorted every word beyond use.","ru":"Трубы исказили слова до полной бесполезности.","tag":"NOISE"}],"correct":0,"vocab":["obsolete dialect — устаревший диалект","establish — установить","formal register — официальный стиль"],"fact":1,"witness":1,"doc":0},{"seg":3,"loc":"Courier station · 11:50","title":"A Package Addressed to “The Next You”","titleRu":"Посылка для «следующей версии вас»","body":"Courier Dorian Pike delivered a sealed box to the apartment three days earlier. The recipient line read: “To the next version of the investigator, after the body is found.” He was paid with a memory of a summer he never lived.","bodyRu":"Курьер Дориан Пайк доставил запечатанную коробку за три дня до событий. Получатель был указан так: «Следующей версии следователя — после обнаружения тела». Ему заплатили воспоминанием о лете, которого он не проживал.","task":"What does the wording imply?","taskRu":"Что означает такая формулировка?","opts":[{"en":"The sender expected your identity to change during the case.","ru":"Отправитель ожидал, что ваша личность изменится во время дела.","tag":"PREDICTION"},{"en":"The sender did not know your name.","ru":"Отправитель не знал вашего имени.","tag":"MISTAKE"},{"en":"It was only a courier joke.","ru":"Это была лишь шутка курьера.","tag":"JOKE"}],"correct":0,"vocab":["recipient line — строка получателя","wording — формулировка","expect — ожидать"],"fact":1,"witness":1,"doc":1},{"seg":3,"loc":"Night gate · 12:20","title":"Nessa Crow Saw the Victim Leave","titleRu":"Несса Кроу видела, как погибшая ушла","body":"The night guard insists the victim left the building alive at 00:06—seven minutes after the official time of death. Yet the body was already inside. Nessa describes the departing woman as faceless only when seen in reflection.","bodyRu":"Ночной охранник утверждает, что погибшая покинула дом живой в 00:06 — через семь минут после официального времени смерти. Но тело уже находилось внутри. В отражении лицо уходящей женщины исчезало.","task":"Which explanation fits all details?","taskRu":"Какое объяснение соответствует всем деталям?","opts":[{"en":"The victim’s identity left in another body while the original shell remained.","ru":"Личность погибшей ушла в другом теле, а исходная оболочка осталась.","tag":"SPLIT"},{"en":"A conventional ghost carried the body away.","ru":"Обычный призрак унёс тело.","tag":"GHOST"},{"en":"Every clock in the district was wrong by chance.","ru":"Все часы района случайно показывали неверное время.","tag":"FALSE TIME"}],"correct":0,"vocab":["shell — оболочка","departing — уходящий","reflection — отражение"],"fact":1,"witness":1,"doc":0},{"seg":3,"loc":"Ministry vestibule · 12:50","title":"The Clerk Was Ordered to Forget You","titleRu":"Служащему приказали забыть вас","body":"A junior clerk recognises you, then immediately recites a memorised denial: “I have never met this investigator.” Under pressure, he reveals a standing order requiring staff to forget you after every seventeenth-day reset.","bodyRu":"Младший служащий узнаёт вас, а затем механически произносит: «Я никогда не встречал этого следователя». Под давлением он сообщает о постоянном приказе забывать вас после каждого перезапуска семнадцатого дня.","task":"What does the order prove?","taskRu":"Что доказывает приказ?","opts":[{"en":"You repeatedly return to the same investigation cycle.","ru":"Вы неоднократно возвращаетесь к одному циклу расследования.","tag":"RECURRING ROLE"},{"en":"The clerk personally dislikes you.","ru":"Служащий лично вас не любит.","tag":"PERSONAL GRUDGE"},{"en":"All visitors are forgotten every evening.","ru":"Всех посетителей забывают каждый вечер.","tag":"SECURITY ROUTINE"}],"correct":0,"vocab":["standing order — постоянный приказ","recite — произносить заученное","recurring — повторяющийся"],"fact":1,"witness":1,"doc":1},{"seg":4,"loc":"Language Chapel · 13:30","title":"The Missing Agent","titleRu":"Отсутствующий исполнитель","body":"Irene isolates four passive sentences in the victim’s letters: “The city was rewritten. The body was prepared. The witness was retained. The investigator was returned.” None names the person responsible.","bodyRu":"Irene выделяет четыре пассивные фразы: «Город был переписан. Тело было подготовлено. Свидетель была сохранена. Следователь был возвращён». Ни одна не называет исполнителя.","task":"What pattern should you investigate?","taskRu":"Какую закономерность следует исследовать?","opts":[{"en":"The same hidden agent may control all four actions.","ru":"Один скрытый исполнитель может управлять всеми четырьмя действиями.","tag":"AGENT"},{"en":"The victim did not understand English grammar.","ru":"Погибшая не понимала английскую грамматику.","tag":"GRAMMAR ERROR"},{"en":"Passive voice has no investigative value.","ru":"Пассивный залог не имеет значения для расследования.","tag":"STYLE"}],"correct":0,"vocab":["hidden agent — скрытый исполнитель","responsible — ответственный","passive sentence — пассивное предложение"],"fact":1,"witness":0,"doc":0},{"seg":4,"loc":"Syntax table · 13:55","title":"“If I Forget, You Will Arrive”","titleRu":"«Если я забуду, вы придёте»","body":"The conditional in the victim’s note predicts your arrival as the result of her forgetting. It does not say “if I die.” Irene argues that the loss of identity, not physical death, was the trigger.","bodyRu":"Условная конструкция предсказывает ваше прибытие как следствие её забвения. В записке не сказано «если я умру». Irene считает, что спусковым механизмом стала потеря личности, а не физическая смерть.","task":"What was designed to summon you?","taskRu":"Что было создано, чтобы вызвать вас?","opts":[{"en":"The deliberate erasure of the victim’s memory.","ru":"Намеренное стирание памяти погибшей.","tag":"TRIGGER"},{"en":"Only the physical death of the body.","ru":"Только физическая смерть тела.","tag":"MURDER"},{"en":"The paper itself, independent of events.","ru":"Сам лист бумаги независимо от событий.","tag":"LETTER"}],"correct":0,"vocab":["conditional — условная конструкция","trigger — спусковой механизм","erasure — стирание"],"fact":1,"witness":0,"doc":0},{"seg":4,"loc":"Pronoun map · 14:20","title":"Who Is “She”?","titleRu":"Кто такая «она»?","body":"In three letters, the pronoun “she” alternately refers to the victim, Irene, and the city itself. The shifts occur at exact intervals of seventeen lines. The ambiguity is structured, not accidental.","bodyRu":"В трёх письмах местоимение «она» поочерёдно обозначает погибшую, Irene и сам город. Смена происходит через каждые семнадцать строк. Двусмысленность организована намеренно.","task":"What should the pronoun shifts be treated as?","taskRu":"Чем следует считать смену местоимений?","opts":[{"en":"A coded sequence linking woman, curator, and city.","ru":"Шифром, связывающим женщину, куратора и город.","tag":"CIPHER"},{"en":"Random confusion caused by stress.","ru":"Случайной путаницей из-за стресса.","tag":"CONFUSION"},{"en":"A simple printing error.","ru":"Обычной опечаткой.","tag":"TYPO"}],"correct":0,"vocab":["pronoun — местоимение","ambiguity — двусмысленность","structured — организованный"],"fact":1,"witness":0,"doc":0},{"seg":4,"loc":"Acrostic desk · 14:45","title":"The First Letters Spell a Name","titleRu":"Первые буквы образуют имя","body":"The first letter of each paragraph spells LYRA. The name appears nowhere in official records, but the hidden study contains a photograph marked “Lyra, before the division.”","bodyRu":"Первые буквы абзацев образуют имя LYRA. В официальных документах такого имени нет, однако в тайном кабинете есть фотография с подписью: «Лира, до разделения».","task":"How should Lyra be classified for now?","taskRu":"Как пока следует классифицировать Лиру?","opts":[{"en":"A possible original identity connected to the victim and you.","ru":"Возможная первоначальная личность, связанная с погибшей и вами.","tag":"UNKNOWN IDENTITY"},{"en":"The proven murderer.","ru":"Доказанная убийца.","tag":"CONFIRMED KILLER"},{"en":"A decorative word with no significance.","ru":"Декоративное слово без значения.","tag":"IRRELEVANT NAME"}],"correct":0,"vocab":["acrostic — акростих","division — разделение","classify — классифицировать"],"fact":1,"witness":0,"doc":0},{"seg":4,"loc":"Tense reconstruction · 15:10","title":"A Future Written in the Past","titleRu":"Будущее, написанное в прошлом","body":"One sentence reads: “When you remembered this, I had already left.” The tense treats your future memory as a completed event. The writer had experienced this investigation before—or expected it to repeat.","bodyRu":"В одной фразе сказано: «Когда вы это вспомнили, я уже ушла». Время представляет ваше будущее воспоминание как завершённое событие. Автор уже переживал это расследование или ожидал его повторения.","task":"Which hypothesis gains support?","taskRu":"Какая гипотеза получает подтверждение?","opts":[{"en":"The case has occurred in earlier identity cycles.","ru":"Дело уже происходило в прежних циклах личности.","tag":"CYCLE"},{"en":"The victim simply guessed every event.","ru":"Погибшая лишь угадала все события.","tag":"PROPHECY ONLY"},{"en":"Verb tense cannot reveal chronology.","ru":"Время глагола не отражает хронологию.","tag":"NO MEANING"}],"correct":0,"vocab":["completed event — завершённое событие","cycle — цикл","chronology — хронология"],"fact":1,"witness":0,"doc":0},{"seg":5,"loc":"Oren’s laboratory · 16:00","title":"The Sample Is Still Thinking","titleRu":"Образец продолжает мыслить","body":"Oren places a drop of the victim’s memory residue into a crystal dish. The residue responds to your questions by changing colour. It reacts most strongly to the words “sister,” “anchor,” and “Lyra.”","bodyRu":"Орен помещает каплю следа памяти погибшей в кристаллическую чашу. Образец меняет цвет в ответ на вопросы и сильнее всего реагирует на слова «сестра», «якорь» и «Лира».","task":"What does the response demonstrate?","taskRu":"Что показывает реакция?","opts":[{"en":"Part of the victim’s conscious pattern remains active.","ru":"Часть сознательной структуры погибшей остаётся активной.","tag":"SURVIVAL"},{"en":"The liquid is merely toxic.","ru":"Жидкость просто ядовита.","tag":"POISON"},{"en":"Oren controls every colour by hand.","ru":"Орен вручную управляет каждым цветом.","tag":"Oren’s trick"}],"correct":0,"vocab":["residue — остаточный след","conscious pattern — структура сознания","respond — реагировать"],"fact":1,"witness":0,"doc":0},{"seg":5,"loc":"Oren’s laboratory · 16:25","title":"The Ampoule Was Prescribed, Not Stolen","titleRu":"Ампулу выписали, а не украли","body":"Oren admits he prescribed the mixture to the victim under a sealed Ministry order. The authorising signature belongs to Lady Morwen, but the medical instructions were written in your handwriting.","bodyRu":"Орен признаёт, что выписал смесь погибшей по закрытому приказу Министерства. Разрешение подписала Леди Морвен, но медицинские инструкции написаны вашим почерком.","task":"Which fact matters most?","taskRu":"Какой факт наиболее важен?","opts":[{"en":"A previous version of you helped design the procedure.","ru":"Предыдущая версия вас помогла разработать процедуру.","tag":"AUTHORSHIP"},{"en":"Doctors often prescribe medicine.","ru":"Врачи часто выписывают лекарства.","tag":"PRESCRIPTION"},{"en":"Morwen acted without anyone else.","ru":"Морвен действовала полностью одна.","tag":"MORWEN ALONE"}],"correct":0,"vocab":["authorising signature — разрешающая подпись","prescribe — выписывать","procedure — процедура"],"fact":1,"witness":0,"doc":1},{"seg":5,"loc":"Oren’s laboratory · 16:50","title":"A Body Can Hold More Than One Name","titleRu":"Одно тело может хранить несколько имён","body":"Oren explains that the human nervous system can temporarily host several memory patterns, but only if one identity acts as an anchor. If the anchor collapses, the other identities separate violently.","bodyRu":"Орен объясняет, что нервная система может временно хранить несколько структур памяти, но только если одна личность служит якорем. При распаде якоря остальные личности разделяются насильственно.","task":"Why might the victim have chosen you?","taskRu":"Почему погибшая могла выбрать вас?","opts":[{"en":"Your identity had already been engineered to hold multiple histories.","ru":"Ваша личность уже была создана для хранения нескольких историй.","tag":"ANCHOR"},{"en":"You were the most famous investigator.","ru":"Вы были самым известным следователем.","tag":"FAME"},{"en":"She selected a stranger at random.","ru":"Она случайно выбрала незнакомца.","tag":"CHANCE"}],"correct":0,"vocab":["host — вмещать","anchor — якорь","collapse — распад"],"fact":1,"witness":0,"doc":0},{"seg":5,"loc":"Oren’s laboratory · 17:15","title":"Oren Deleted His Own Memory","titleRu":"Орен удалил собственную память","body":"A scar behind Oren’s ear matches the extraction device. He admits removing the final ten minutes of the procedure from his own mind so the Ministry could not take them. He stored the memory in an unknown patient.","bodyRu":"Шрам за ухом Орена совпадает с устройством извлечения. Он признаётся, что удалил последние десять минут процедуры из собственной памяти, чтобы Министерство не получило их. Воспоминание хранится в неизвестном пациенте.","task":"What is the immediate investigative priority?","taskRu":"Какова ближайшая задача расследования?","opts":[{"en":"Identify the patient carrying Oren’s missing memory.","ru":"Найти пациента, хранящего отсутствующее воспоминание Орена.","tag":"LOCATE PATIENT"},{"en":"Arrest Oren before asking anything else.","ru":"Арестовать Орена, не задавая больше вопросов.","tag":"ARREST"},{"en":"The missing ten minutes cannot matter.","ru":"Недостающие десять минут не могут быть важны.","tag":"IGNORE"}],"correct":0,"vocab":["extraction device — устройство извлечения","store a memory — хранить воспоминание","priority — приоритет"],"fact":1,"witness":1,"doc":0},{"seg":5,"loc":"Oren’s laboratory · 17:40","title":"The Patient Is Mara Holt","titleRu":"Пациент — Мара Холт","body":"Oren’s ledger reveals that Mara volunteered to carry his missing memory. Her decade-long gap was not empty: she spent those years preserving fragments that could survive each reset.","bodyRu":"Реестр Орена показывает, что Мара добровольно хранила его память. Её десятилетний пробел не был пустым: все эти годы она сохраняла фрагменты, способные пережить каждый перезапуск.","task":"How does this change Mara’s role?","taskRu":"Как это меняет роль Мары?","opts":[{"en":"She is an unofficial living archive, not merely a caretaker.","ru":"Она является неофициальным живым архивом, а не просто смотрительницей.","tag":"ARCHIVIST"},{"en":"She must be the sole murderer.","ru":"Она обязательно единственная убийца.","tag":"SUSPECT ONLY"},{"en":"She knows nothing important.","ru":"Она не знает ничего важного.","tag":"BYSTANDER"}],"correct":0,"vocab":["volunteer — добровольно согласиться","living archive — живой архив","fragment — фрагмент"],"fact":1,"witness":1,"doc":1},{"seg":6,"loc":"Evidence hall · 18:20","title":"Morwen Had Authority but Not Privacy","titleRu":"У Морвен была власть, но не тайна","body":"Morwen could authorise the procedure, yet her office was monitored throughout the night. She had the means to order the extraction but could not personally arrange the apartment without accomplices.","bodyRu":"Морвен могла санкционировать процедуру, но её кабинет всю ночь находился под наблюдением. Она могла приказать провести извлечение, но не могла самостоятельно подготовить квартиру без сообщников.","task":"How should her role be described?","taskRu":"Как следует описать её роль?","opts":[{"en":"A likely organiser with incomplete control over the operation.","ru":"Вероятный организатор с неполным контролем над операцией.","tag":"ORGANISER"},{"en":"The only person involved.","ru":"Единственный участник.","tag":"SOLE KILLER"},{"en":"Completely unrelated to the case.","ru":"Полностью не связана с делом.","tag":"INNOCENT"}],"correct":0,"vocab":["authority — полномочия","accomplice — сообщник","incomplete control — неполный контроль"],"fact":1,"witness":0,"doc":0},{"seg":6,"loc":"Evidence hall · 18:45","title":"Silas Lied About the First Meeting","titleRu":"Сайлас солгал о первой встрече","body":"Silas claimed he first met the victim three nights before her death, but an eighty-year-old lease bears his witness signature. The ink is authentic. Either Silas has lived through multiple cycles, or the signature was carried by another version of him.","bodyRu":"Сайлас утверждал, что впервые встретил погибшую за три ночи до её смерти, однако на договоре восьмидесятилетней давности стоит его подпись свидетеля. Чернила подлинные. Либо Сайлас пережил несколько циклов, либо подпись принадлежала другой его версии.","task":"What question becomes essential?","taskRu":"Какой вопрос становится ключевым?","opts":[{"en":"Which version of Silas is speaking to you now?","ru":"Какая версия Сайласа сейчас говорит с вами?","tag":"IDENTITY HISTORY"},{"en":"Whether he writes neatly.","ru":"Аккуратно ли он пишет.","tag":"HANDWRITING"},{"en":"Where he ate breakfast today.","ru":"Где он сегодня завтракал.","tag":"ALIBI ONLY"}],"correct":0,"vocab":["authentic ink — подлинные чернила","essential — ключевой","version — версия"],"fact":1,"witness":0,"doc":0},{"seg":6,"loc":"Evidence hall · 19:10","title":"The Victim Planned Her Own Discovery","titleRu":"Погибшая спланировала собственное обнаружение","body":"The early death certificate, courier package, layered clock, and mirror trigger all required preparation before the body appeared. The victim participated in designing the scene.","bodyRu":"Раннее свидетельство о смерти, посылка, двойное время часов и зеркальный спусковой механизм требовали подготовки до появления тела. Погибшая участвовала в создании сцены.","task":"Does participation eliminate the possibility of a crime?","taskRu":"Исключает ли её участие возможность преступления?","opts":[{"en":"No. Consent to one procedure does not prove consent to every later action.","ru":"Нет. Согласие на одну процедуру не означает согласия на все последующие действия.","tag":"NO"},{"en":"Yes. A planned scene can never contain a crime.","ru":"Да. В спланированной сцене преступления быть не может.","tag":"YES"},{"en":"The question should never be investigated.","ru":"Этот вопрос не следует расследовать.","tag":"UNKNOWN"}],"correct":0,"vocab":["participation — участие","consent — согласие","eliminate — исключать"],"fact":1,"witness":0,"doc":0},{"seg":6,"loc":"Evidence hall · 19:35","title":"A Previous You Left Instructions","titleRu":"Предыдущая версия вас оставила инструкции","body":"Your handwriting appears in the medical order, the courier code, and a note hidden behind the mirror: “Do not trust the conclusion I wanted you to reach.” A previous version of you helped build the puzzle and feared its own motive.","bodyRu":"Ваш почерк присутствует в медицинском приказе, курьерском коде и записке за зеркалом: «Не доверяйте выводу, к которому я хотел вас привести». Предыдущая версия вас помогала строить загадку и боялась собственного мотива.","task":"How should your earlier self be treated?","taskRu":"Как следует относиться к прежней версии себя?","opts":[{"en":"As both a suspect and a source of evidence.","ru":"Одновременно как к подозреваемому и источнику улик.","tag":"SUSPECT AND SOURCE"},{"en":"As automatically trustworthy because it was you.","ru":"Как к безусловно надёжному источнику, потому что это были вы.","tag":"AUTHORITATIVE"},{"en":"As unrelated to your present investigation.","ru":"Как к человеку, не связанному с нынешним расследованием.","tag":"IRRELEVANT"}],"correct":0,"vocab":["earlier self — прежняя версия себя","source of evidence — источник улик","motive — мотив"],"fact":1,"witness":0,"doc":0},{"seg":6,"loc":"Evidence hall · 20:00","title":"The Crime Needed Four Roles","titleRu":"Для преступления требовались четыре роли","body":"The reconstruction requires an authoriser, a physician, a living archive, and an anchor. Morwen, Oren, Mara, and a previous version of you fit those roles. Silas appears to have been the interrupter who tore the thread.","bodyRu":"Для реконструкции необходимы тот, кто разрешил процедуру, врач, живой архив и якорь. Этим ролям соответствуют Морвен, Орен, Мара и прежняя версия вас. Сайлас, вероятно, пытался вмешаться и разорвал нить.","task":"What type of event was this?","taskRu":"К какому типу события это относится?","opts":[{"en":"A coordinated operation that broke apart during execution.","ru":"Согласованная операция, распавшаяся во время выполнения.","tag":"CONSPIRACY WITH CONFLICT"},{"en":"A simple murder by one person.","ru":"Простое убийство, совершённое одним человеком.","tag":"LONE MURDER"},{"en":"An unrelated household accident.","ru":"Несвязанный бытовой несчастный случай.","tag":"ACCIDENT"}],"correct":0,"vocab":["coordinated operation — согласованная операция","execution — выполнение","interrupter — вмешавшийся человек"],"fact":1,"witness":0,"doc":0},{"seg":7,"loc":"Apartment 17 · 20:40","title":"23:41 — The Procedure Begins","titleRu":"23:41 — процедура начинается","body":"The boiler pressure rises as the hidden study is sealed. Mara carries Oren’s protected memory. Morwen’s authorisation opens the Ministry channel. The victim enters the chair voluntarily.","bodyRu":"Давление в котельной растёт, когда тайный кабинет запечатывают. Мара хранит защищённую память Орена. Разрешение Морвен открывает канал Министерства. Погибшая добровольно садится в кресло.","task":"Which fact remains unresolved at this moment?","taskRu":"Какой вопрос пока остаётся нерешённым?","opts":[{"en":"What exactly the victim agreed would happen after extraction.","ru":"На что именно погибшая согласилась после извлечения.","tag":"CONSENT LIMITS"},{"en":"Whether the apartment exists.","ru":"Существует ли квартира.","tag":"LOCATION"},{"en":"Whether Mara works in the building.","ru":"Работает ли Мара в доме.","tag":"MARA"}],"correct":0,"vocab":["voluntarily — добровольно","unresolved — нерешённый","after extraction — после извлечения"],"fact":1,"witness":0,"doc":0},{"seg":7,"loc":"Apartment 17 · 21:05","title":"23:59 — Identity Leaves the Body","titleRu":"23:59 — личность покидает тело","body":"The clock records the completed extraction. The victim’s identity divides: one part enters a prepared body and leaves through the roof route; another remains distributed among Mara, the mirror, and the package. The original body becomes the faceless shell.","bodyRu":"Часы фиксируют завершение извлечения. Личность погибшей разделяется: одна часть входит в подготовленное тело и уходит через крышу, другая распределяется между Марой, зеркалом и посылкой. Исходное тело становится безликой оболочкой.","task":"Was the victim entirely dead at 23:59?","taskRu":"Была ли погибшая полностью мертва в 23:59?","opts":[{"en":"No. Her identity survived in several active containers.","ru":"Нет. Её личность сохранилась в нескольких активных носителях.","tag":"NO"},{"en":"Yes. Identity fragments have no significance.","ru":"Да. Фрагменты личности ничего не значат.","tag":"YES"},{"en":"The evidence cannot address survival at all.","ru":"Улики вообще не позволяют говорить о выживании.","tag":"UNKNOWN FOREVER"}],"correct":0,"vocab":["distributed — распределённый","container — носитель","shell — оболочка"],"fact":1,"witness":0,"doc":0},{"seg":7,"loc":"Apartment 17 · 21:30","title":"00:03 — Silas Interrupts the Plan","titleRu":"00:03 — Сайлас вмешивается","body":"Silas arrives earlier than expected, sees the identity division, and tears the silver thread by hand. His intervention prevents the Ministry from collecting every fragment but destabilises the victim’s escape.","bodyRu":"Сайлас приходит раньше, видит разделение личности и разрывает серебряную нить рукой. Его вмешательство не позволяет Министерству собрать все фрагменты, но нарушает побег погибшей.","task":"How should Silas’s action be classified?","taskRu":"Как классифицировать действие Сайласа?","opts":[{"en":"An attempted rescue that caused additional damage.","ru":"Попытка спасения, вызвавшая дополнительные повреждения.","tag":"RESCUE WITH CONSEQUENCES"},{"en":"A deliberate killing with no other motive.","ru":"Преднамеренное убийство без иной цели.","tag":"EXECUTION"},{"en":"An action unrelated to the victim’s condition.","ru":"Действие, не связанное с состоянием погибшей.","tag":"IRRELEVANT"}],"correct":0,"vocab":["intervention — вмешательство","destabilise — нарушить устойчивость","consequence — последствие"],"fact":1,"witness":0,"doc":0},{"seg":7,"loc":"Apartment 17 · 21:55","title":"00:06 — One Version Leaves","titleRu":"00:06 — одна версия уходит","body":"Nessa sees the transferred version leave the building. It carries enough of the victim to speak and choose, but not enough to remember where the remaining fragments were hidden. The escape was real but incomplete.","bodyRu":"Несса видит, как перенесённая версия покидает дом. В ней достаточно личности, чтобы говорить и выбирать, но недостаточно, чтобы помнить расположение остальных фрагментов. Побег состоялся, но остался неполным.","task":"What should the missing person alert describe?","taskRu":"Как следует сформулировать розыск?","opts":[{"en":"A living identity fragment using an unknown body.","ru":"Живой фрагмент личности в неизвестном теле.","tag":"LIVING FRAGMENT"},{"en":"Only the body left in Apartment 17.","ru":"Только тело, оставленное в квартире.","tag":"CORPSE"},{"en":"Silas as the victim.","ru":"Сайласа как погибшего.","tag":"SILAS"}],"correct":0,"vocab":["missing person alert — ориентировка","incomplete — неполный","unknown body — неизвестное тело"],"fact":1,"witness":0,"doc":0},{"seg":7,"loc":"Apartment 17 · 22:20","title":"02:17 — The Mirror Calls You","titleRu":"02:17 — зеркало вызывает вас","body":"The mirror activates when your voice enters the room. It recognises the anchor signature planted in every version of you. The scene was designed so only you could unlock the distributed testimony.","bodyRu":"Зеркало активируется, когда в комнате звучит ваш голос. Оно узнаёт подпись якоря, встроенную в каждую вашу версию. Сцену создали так, чтобы только вы могли открыть распределённые свидетельства.","task":"Why was your name burned into the palm?","taskRu":"Почему ваше имя выжгли на ладони?","opts":[{"en":"To guarantee that the Archive assigned you and activated the correct anchor.","ru":"Чтобы Архив назначил именно вас и активировал нужный якорь.","tag":"AUTHENTICATION"},{"en":"Only to frighten you.","ru":"Только чтобы напугать вас.","tag":"REVENGE"},{"en":"As meaningless decoration.","ru":"Как бессмысленное украшение.","tag":"DECORATION"}],"correct":0,"vocab":["authentication — подтверждение личности","assign — назначить","anchor signature — подпись якоря"],"fact":1,"witness":0,"doc":0}];

function renderLongCase(){
 if(state.longCaseStep>=longCaseNodes.length){state.longCaseDone=true;state.memoryStage=0;save();showIrene(isEnglishLevel(state.level)?'The extended case file is complete. You now have enough evidence to enter the victim’s memory without relying on the Ministry’s version.':'Расширенное досье завершено. Теперь у вас достаточно улик, чтобы войти в память погибшей, не полагаясь на версию Министерства.');setTimeout(()=>{closeIrene();go('memory')},1200);return}
 const n=longCaseNodes[state.longCaseStep],s=longCaseSegments[n.seg],a1=(state.level==='A1'||state.level==='A0'),b1=isEnglishLevel(state.level);
 document.getElementById('longCaseTopProgress').textContent=(state.longCaseStep+1)+'/'+longCaseNodes.length;
 document.getElementById('longCaseScore').textContent=state.longCaseScore;
 document.getElementById('longCaseStability').textContent=state.stability;
 document.getElementById('longCaseKicker').textContent=b1?s.k:s.kRu;
 document.getElementById('longCaseHeading').textContent=b1?s.title:s.titleRu;
 document.getElementById('longCaseSegment').textContent=(b1?'Section ':'Раздел ')+(n.seg+1)+' / '+longCaseSegments.length;
 document.getElementById('longCaseEstimate').textContent=b1?'Estimated first case: 1 h 45–2 h 15':'Расчётное время первого дела: 1 ч 45 мин – 2 ч 15 мин';
 document.getElementById('longCaseChapter').textContent=b1?s.title:s.titleRu;
 document.getElementById('longCaseChapterDesc').textContent=b1?s.desc:s.descRu;
 document.getElementById('longCaseSymbol').textContent=s.symbol;
 document.getElementById('longCaseLocation').textContent=n.loc;
 document.getElementById('longCaseTitle').textContent=(b1||state.level==='A2')?n.title:n.titleRu;
 document.getElementById('longCaseBody').textContent=n.body;
 document.getElementById('longCaseTask').textContent=n.task;
 const tr=document.getElementById('longCaseTranslation');tr.textContent=n.bodyRu+'\n\n'+n.taskRu;tr.classList.toggle('hidden',!a1);
 const voc=document.getElementById('longCaseVocab');voc.innerHTML=b1?'':n.vocab.map(v=>'<span>'+v+'</span>').join('');
 const tools=document.getElementById('longCaseTools');tools.innerHTML='';if(state.level==='A2')tools.innerHTML='<button class="tool-btn" onclick="toggleBox(\'longCaseTranslation\')">Show translation</button>';
 const box=document.getElementById('longCaseOptions');box.innerHTML='';n.opts.forEach((o,i)=>{const b=document.createElement('button');b.className='long-case-option';b.innerHTML='<small>'+o.tag+'</small>'+o.en+(a1?'<span class="ru">'+o.ru+'</span>':'');b.onclick=()=>answerLongCase(i);box.appendChild(b)});
 const pct=((state.longCaseStep+1)/longCaseNodes.length)*100;document.getElementById('longCaseBar').style.width=pct+'%';
 document.getElementById('longCaseFacts').textContent=state.longCaseFacts;document.getElementById('longCaseMistakes').textContent=state.longCaseMistakes;document.getElementById('longCaseWitnesses').textContent=state.longCaseWitnesses;document.getElementById('longCaseDocuments').textContent=state.longCaseDocuments;updateMusicButtons();
}
function answerLongCase(index){
 clickSfx();const n=longCaseNodes[state.longCaseStep],correct=index===n.correct;
 if(correct){state.longCaseScore++;state.longCaseFacts+=n.fact||0;state.longCaseWitnesses+=n.witness||0;state.longCaseDocuments+=n.doc||0;toast(isEnglishLevel(state.level)?'Deduction verified':'Вывод подтверждён')}else{state.longCaseMistakes++;state.stability=Math.max(35,state.stability-2);toast(isEnglishLevel(state.level)?'The conclusion creates a contradiction':'Вывод создаёт противоречие')}
 state.longCaseStep++;save();setTimeout(renderLongCase,correct?520:2600);
}

const campaignNodes={"ministry_start":{"chapter":"CHAPTER II · THE MINISTRY'S MASK","chapterRu":"ГЛАВА II · МАСКА МИНИСТЕРСТВА","kicker":"ORDER ROUTE","title":"The Price of a Quiet City","titleRu":"Цена спокойного города","speaker":"Lady Morwen","role":"Minister of Memory","roleRu":"Министр памяти","img":"morwen","quote":"You gave me the version of the truth I requested. Now I need to know whether you understood the cost.","quoteRu":"Вы дали мне ту версию правды, которую я просила. Теперь мне нужно понять, осознали ли вы цену.","body":"Morwen receives you in the Hall of Sealed Records. Behind her, thousands of glass capsules hold memories confiscated from citizens. She offers you a promotion and access to the Ministry's private ledger—on one condition: you must help erase every trace of the faceless woman.\n\nBefore you answer, one capsule begins to glow with the rhythm of your heartbeat.","bodyRu":"Морвен принимает вас в Зале запечатанных записей. За её спиной тысячи стеклянных капсул хранят воспоминания, изъятые у жителей. Она предлагает повышение и доступ к тайному реестру Министерства — при одном условии: вы должны помочь уничтожить все следы женщины без лица.\n\nПрежде чем вы успеваете ответить, одна из капсул начинает светиться в ритме вашего сердца.","vocab":["confiscated — изъятый","ledger — реестр","on one condition — при одном условии"],"choices":[{"tag":"OBEY","en":"Accept the promotion and examine the ledger from inside the system.","ru":"Принять повышение и изучить реестр изнутри системы.","next":"ministry_ledger","effects":{"align":{"ministry":2},"bonds":{"morwen":2},"influence":2}},{"tag":"DOUBLE GAME","en":"Pretend to agree, then send Irene a coded message.","ru":"Сделать вид, что вы согласны, и отправить Irene зашифрованное сообщение.","next":"irene_cipher","effects":{"align":{"archive":1},"bonds":{"irene":2},"influence":1}},{"tag":"BARGAIN","en":"Demand to see the victim's confiscated memory before you erase anything.","ru":"Потребовать показать изъятое воспоминание погибшей, прежде чем что-либо стирать.","next":"morwen_bargain","effects":{"bonds":{"morwen":1},"influence":2,"stability":-3}}]},"ministry_ledger":{"chapter":"CHAPTER II · THE MINISTRY'S MASK","chapterRu":"ГЛАВА II · МАСКА МИНИСТЕРСТВА","kicker":"CLASSIFIED LEDGER","title":"Seventeen Missing Days","titleRu":"Семнадцать пропавших дней","speaker":"Lady Morwen","role":"Minister of Memory","roleRu":"Министр памяти","img":"morwen","quote":"The city does not have a history. It has a maintenance schedule.","quoteRu":"У города нет истории. У него есть график технического обслуживания.","body":"The private ledger does not list crimes. It lists dates on which entire districts were reset. Every seventeenth day, the same sequence appears: unrest, mass memory extraction, reconstruction.\n\nYour own signature authorises nine of the resets—even those dated long before your official birth.","bodyRu":"Тайный реестр содержит не преступления, а даты, когда целые районы перезапускались. Каждый семнадцатый день повторяется одна и та же последовательность: беспорядки, массовое извлечение памяти, восстановление.\n\nВаша подпись санкционирует девять таких перезапусков — даже те, которые произошли задолго до вашей официальной даты рождения.","vocab":["maintenance schedule — график обслуживания","authorise — санкционировать","reset — перезапуск"],"choices":[{"tag":"CONFRONT","en":"Ask Morwen why your signature appears before your birth.","ru":"Спросить Морвен, почему ваша подпись стоит под документами до вашего рождения.","next":"glass_council","effects":{"bonds":{"morwen":1},"addSecret":"seventeen_day","stability":-5}},{"tag":"COPY","en":"Secretly copy the ledger and hide the original evidence.","ru":"Тайно скопировать реестр и спрятать оригинальные доказательства.","next":"language_chapel","effects":{"align":{"archive":1},"bonds":{"irene":1},"addSecret":"seventeen_day","influence":1}}]},"morwen_bargain":{"chapter":"CHAPTER II · THE MINISTRY'S MASK","chapterRu":"ГЛАВА II · МАСКА МИНИСТЕРСТВА","kicker":"A POLITICAL BARGAIN","title":"The Memory in the Red Capsule","titleRu":"Воспоминание в красной капсуле","speaker":"Lady Morwen","role":"Minister of Memory","roleRu":"Министр памяти","img":"morwen","quote":"You still believe the dead woman was your sister. That belief was planted because it would make you investigate.","quoteRu":"Вы всё ещё верите, что погибшая была вашей сестрой. Эту мысль внедрили, чтобы заставить вас расследовать.","body":"Morwen unlocks the glowing capsule. Inside, you see yourself standing beside the faceless woman during the destruction of old Evervale. But the woman calls you “Anchor Nine,” not sibling.\n\nMorwen claims the victim designed your false family history as a trigger. She offers the rest of the memory in exchange for your loyalty.","bodyRu":"Морвен открывает светящуюся капсулу. Внутри вы видите себя рядом с женщиной без лица во время гибели старого Эвервейла. Но она называет вас не родственником, а «Якорем Девять».\n\nМорвен утверждает, что погибшая создала вашу ложную семейную историю как спусковой механизм. Она предлагает остаток воспоминания в обмен на верность.","vocab":["planted belief — внедрённое убеждение","trigger — спусковой механизм","in exchange for — в обмен на"],"choices":[{"tag":"LOYALTY","en":"Give Morwen your word and watch the complete memory.","ru":"Дать Морвен слово и посмотреть полное воспоминание.","next":"glass_council","effects":{"align":{"ministry":2},"bonds":{"morwen":2},"addSecret":"anchor_nine"}},{"tag":"REFUSE","en":"Refuse the bargain and ask Irene to decode the phrase “Anchor Nine.”","ru":"Отказаться от сделки и попросить Irene расшифровать выражение «Якорь Девять».","next":"irene_cipher","effects":{"bonds":{"irene":2},"addSecret":"anchor_nine","stability":-2}}]},"glass_council":{"chapter":"CHAPTER II · THE MINISTRY'S MASK","chapterRu":"ГЛАВА II · МАСКА МИНИСТЕРСТВА","kicker":"THE INNER COUNCIL","title":"Morwen's Real Motive","titleRu":"Настоящий мотив Морвен","speaker":"Lady Morwen","role":"Minister of Memory","roleRu":"Министр памяти","img":"morwen","quote":"I did not build the cage. I inherited it—and every day I choose who is allowed to notice the bars.","quoteRu":"Я не строила эту клетку. Я получила её в наследство — и каждый день решаю, кому позволено заметить прутья.","body":"At the Glass Council, Morwen reveals that the memory resets are not merely political control. They keep something beneath the city asleep. Each uncontrolled recollection strengthens the Nameless Queen, whose erased identity is woven into Evervale's foundations.\n\nMorwen is not trying to preserve her power alone. She is preventing the city from remembering the name that could wake its original ruler.","bodyRu":"На заседании Стеклянного совета Морвен раскрывает: перезапуски памяти нужны не только для политического контроля. Они удерживают в спящем состоянии нечто под городом. Каждое неконтролируемое воспоминание усиливает Безымянную Королеву, чья стёртая личность вплетена в основание Эвервейла.\n\nМорвен защищает не только свою власть. Она не даёт городу вспомнить имя, способное разбудить его первоначальную правительницу.","vocab":["inherit — унаследовать","woven into — вплетённый в","original ruler — первоначальный правитель"],"choices":[{"tag":"PROTECT","en":"Help Morwen contain the awakening until you know more.","ru":"Помочь Морвен сдержать пробуждение, пока вы не узнаете больше.","next":"ball_gate","effects":{"align":{"ministry":2},"bonds":{"morwen":2},"addSecret":"morwen_motive"}},{"tag":"INVESTIGATE","en":"Use the Council invitation to enter the House of the Eternal Ball.","ru":"Использовать приглашение Совета, чтобы проникнуть в Дом вечного бала.","next":"ball_gate","effects":{"align":{"archive":1},"addSecret":"morwen_motive"}}]},"irene_cipher":{"chapter":"CHAPTER II · THE LIVING LANGUAGE","chapterRu":"ГЛАВА II · ЖИВОЙ ЯЗЫК","kicker":"IRENE'S PRIVATE CHANNEL","title":"A Sentence That Remembers You","titleRu":"Предложение, которое вас помнит","speaker":"Irene Vale","role":"Language Curator","roleRu":"Куратор языка","img":"irene","quote":"The message you sent me changed one word after I read it. That means the language itself is alive.","quoteRu":"После того как я прочитала ваше сообщение, в нём изменилось одно слово. Значит, сам язык живой.","body":"Irene decodes your message and discovers a second layer hidden inside its grammar. The sentence is not only information—it is a memory spell. When she reads it aloud, a door appears behind the shelves of the Language Chapel.\n\nOn the door is written: “For the conscience of Anchor Nine.”","bodyRu":"Irene расшифровывает сообщение и обнаруживает второй слой, спрятанный в грамматике. Предложение является не только информацией, но и заклинанием памяти. Когда она произносит его вслух, за полками Языковой часовни появляется дверь.\n\nНа двери написано: «Для совести Якоря Девять».","vocab":["second layer — второй слой","read aloud — прочитать вслух","conscience — совесть"],"choices":[{"tag":"OPEN","en":"Open the door with Irene and enter the hidden chapel.","ru":"Открыть дверь вместе с Irene и войти в скрытую часовню.","next":"language_chapel","effects":{"bonds":{"irene":2},"align":{"archive":1}}},{"tag":"TEST","en":"Ask Irene to prove that the message is not manipulating both of you.","ru":"Попросить Irene доказать, что сообщение не манипулирует вами обоими.","next":"language_chapel","effects":{"bonds":{"irene":1},"stability":2,"influence":1}}]},"language_chapel":{"chapter":"CHAPTER II · THE LIVING LANGUAGE","chapterRu":"ГЛАВА II · ЖИВОЙ ЯЗЫК","kicker":"THE LANGUAGE CHAPEL","title":"Irene Was Not Born","titleRu":"Irene не рождалась","speaker":"Irene Vale","role":"Language Curator","roleRu":"Куратор языка","img":"irene","quote":"I remember teaching you as a child. The problem is that the records say I was created three years ago.","quoteRu":"Я помню, как учила вас в детстве. Проблема в том, что записи утверждают: меня создали три года назад.","body":"The chapel contains thousands of sentences written in your handwriting. Together they form Irene's earliest memories. She realises she was assembled from the moral and linguistic fragments removed from you during reconstruction.\n\nShe is not merely your mentor. She is the part of your original conscience that the Archive could not safely leave inside you.","bodyRu":"В часовне хранятся тысячи предложений, написанных вашим почерком. Вместе они образуют самые ранние воспоминания Irene. Она понимает, что была собрана из моральных и языковых фрагментов, удалённых из вас при восстановлении.\n\nОна не просто наставница. Она — часть вашей первоначальной совести, которую Архив не решился оставить внутри вас.","vocab":["assembled from — собранный из","moral fragment — моральный фрагмент","safely leave — безопасно оставить"],"choices":[{"tag":"TRUST","en":"Tell Irene that being created does not make her less real.","ru":"Сказать Irene, что искусственное создание не делает её менее настоящей.","next":"ball_gate","effects":{"bonds":{"irene":3},"addSecret":"irene_origin","stability":3}},{"tag":"DISTANCE","en":"Ask whether her loyalty is genuine or part of her design.","ru":"Спросить, является ли её верность настоящей или частью программы.","next":"ball_gate","effects":{"bonds":{"irene":-1},"addSecret":"irene_origin","influence":2}}]},"truth_start":{"chapter":"CHAPTER II · THE CITY AWAKENS","chapterRu":"ГЛАВА II · ГОРОД ПРОБУЖДАЕТСЯ","kicker":"RESISTANCE ROUTE","title":"The First Night of Unrest","titleRu":"Первая ночь беспорядков","speaker":"Kael Dusk","role":"Shadow Hunter","roleRu":"Охотник на тени","img":"kael","quote":"You gave the city the truth. Now decide whether you are willing to survive what truth does to people.","quoteRu":"Вы дали городу правду. Теперь решите, готовы ли вы пережить то, что правда делает с людьми.","body":"The Upper District burns with recovered memories. Some citizens embrace forgotten families; others remember crimes they committed under erased identities. Kael finds you among the riots and offers three paths: raid a Ministry convoy, protect witnesses in the flooded archive, or meet Morwen before civil war becomes inevitable.","bodyRu":"Верхний квартал горит от возвращённых воспоминаний. Одни жители находят забытые семьи, другие вспоминают преступления, совершённые под стёртыми личностями. Каэль находит вас среди беспорядков и предлагает три пути: напасть на конвой Министерства, защитить свидетелей в затопленном архиве или встретиться с Морвен до начала неизбежной гражданской войны.","vocab":["unrest — беспорядки","convoy — конвой","inevitable — неизбежный"],"choices":[{"tag":"RAID","en":"Join Kael's raid and seize the Ministry's memory cargo.","ru":"Присоединиться к рейду Каэля и захватить груз воспоминаний Министерства.","next":"forest_gate","effects":{"align":{"freedom":2},"bonds":{"kael":2},"influence":2,"stability":-5}},{"tag":"PROTECT","en":"Lead the witnesses to safety through the drowned archive.","ru":"Провести свидетелей в безопасное место через затопленный архив.","next":"drowned_archive","effects":{"align":{"freedom":1},"bonds":{"irene":1},"stability":2}},{"tag":"NEGOTIATE","en":"Meet Morwen and demand a temporary truce.","ru":"Встретиться с Морвен и потребовать временного перемирия.","next":"morwen_truce","effects":{"bonds":{"morwen":1},"influence":3}}]},"forest_gate":{"chapter":"CHAPTER II · THE CITY AWAKENS","chapterRu":"ГЛАВА II · ГОРОД ПРОБУЖДАЕТСЯ","kicker":"THE NIGHT CONVOY","title":"The Cargo Is Still Dreaming","titleRu":"Груз всё ещё видит сны","speaker":"Kael Dusk","role":"Shadow Hunter","roleRu":"Охотник на тени","img":"kael","quote":"Those are not bottles. Each one contains a person the Ministry decided was easier to store than to control.","quoteRu":"Это не бутылки. В каждой находится человек, которого Министерству оказалось проще хранить, чем контролировать.","body":"The convoy crosses the silver forest outside the city walls. When you open the first transport case, you find living memories—conscious personalities reduced to blue flame. One of them recognises you and calls you the architect of their prison.\n\nKael wants to free them immediately, even if the release tears open the city's protective boundary.","bodyRu":"Конвой пересекает серебряный лес за городскими стенами. В первом транспортном ящике вы находите живые воспоминания — сознательные личности, сведённые к синему пламени. Одна из них узнаёт вас и называет архитектором их тюрьмы.\n\nКаэль хочет освободить их немедленно, даже если это разорвёт защитную границу города.","vocab":["reduced to — сведённый к","protective boundary — защитная граница","tear open — разорвать"],"choices":[{"tag":"FREE THEM","en":"Release the stored minds and accept the consequences.","ru":"Освободить сохранённые сознания и принять последствия.","next":"shadow_hunt","effects":{"align":{"freedom":3},"bonds":{"kael":2},"stability":-10,"addSecret":"living_prisoners"}},{"tag":"DELAY","en":"Take the cargo to Irene before breaking the seals.","ru":"Доставить груз Irene, прежде чем ломать печати.","next":"language_chapel","effects":{"bonds":{"irene":2},"addSecret":"living_prisoners"}}]},"shadow_hunt":{"chapter":"CHAPTER II · THE CITY AWAKENS","chapterRu":"ГЛАВА II · ГОРОД ПРОБУЖДАЕТСЯ","kicker":"BEYOND THE WALL","title":"What Hunts Forgotten People","titleRu":"Что охотится на забытых людей","speaker":"Kael Dusk","role":"Shadow Hunter","roleRu":"Охотник на тени","img":"kael","quote":"The shadows do not eat bodies. They eat the proof that a body ever mattered.","quoteRu":"Тени пожирают не тела. Они пожирают доказательство того, что тело когда-либо имело значение.","body":"Freed memories draw creatures from the dark beyond Evervale. During the hunt, Kael discovers that the shadows carry fragments of the Nameless Queen's voice. They are not her servants—they are pieces of citizens erased during previous cycles.\n\nThe monster you kill leaves behind an invitation to the House of the Eternal Ball, written in your blood type but not your handwriting.","bodyRu":"Освобождённые воспоминания привлекают существ из тьмы за пределами Эвервейла. Во время охоты Каэль замечает, что тени говорят фрагментами голоса Безымянной Королевы. Они не её слуги — они части жителей, стёртых во время прошлых циклов.\n\nУбитое существо оставляет приглашение в Дом вечного бала, написанное кровью вашей группы, но не вашим почерком.","vocab":["carry fragments — нести фрагменты","previous cycle — предыдущий цикл","blood type — группа крови"],"choices":[{"tag":"FOLLOW","en":"Use the invitation and enter the Eternal Ball.","ru":"Использовать приглашение и войти в Дом вечного бала.","next":"ball_gate","effects":{"bonds":{"kael":1},"addSecret":"erased_shadows"}},{"tag":"SEND KAEL","en":"Send Kael to protect the refugees while you enter alone.","ru":"Отправить Каэля защищать беженцев, а самому войти в одиночку.","next":"ball_gate","effects":{"bonds":{"kael":2},"influence":1,"addSecret":"erased_shadows"}}]},"drowned_archive":{"chapter":"CHAPTER II · THE CITY AWAKENS","chapterRu":"ГЛАВА II · ГОРОД ПРОБУЖДАЕТСЯ","kicker":"THE FLOODED VAULTS","title":"Books That Remember Drowning","titleRu":"Книги, которые помнят утопление","speaker":"Irene Vale","role":"Language Curator","roleRu":"Куратор языка","img":"irene","quote":"Do not read the titles aloud. Some of these books think a name is permission to become real.","quoteRu":"Не читайте названия вслух. Некоторые книги считают имя разрешением стать реальностью.","body":"You guide frightened witnesses through submerged vaults where books swim like pale fish. A child finds a volume bearing your chosen face on the cover. Inside, the same investigation is recorded eight times, each ending differently.\n\nIn every version, the seventeenth day ends with you standing before the Eternal Ball.","bodyRu":"Вы ведёте испуганных свидетелей через затопленные хранилища, где книги плавают как бледные рыбы. Ребёнок находит том с лицом выбранного героя на обложке. Внутри одно и то же расследование записано восемь раз и каждый раз заканчивается иначе.\n\nВо всех версиях семнадцатый день завершается тем, что вы стоите перед Домом вечного бала.","vocab":["submerged vault — затопленное хранилище","bearing your face — с вашим лицом","recorded — записанный"],"choices":[{"tag":"READ","en":"Read the eighth ending and risk remembering the previous cycles.","ru":"Прочитать восьмой финал и рискнуть вспомнить предыдущие циклы.","next":"archive_echo","effects":{"stability":-8,"addSecret":"eight_endings"}},{"tag":"SAVE THEM","en":"Close the book and focus on getting the witnesses out alive.","ru":"Закрыть книгу и сосредоточиться на спасении свидетелей.","next":"archive_echo","effects":{"stability":4,"bonds":{"irene":1}}}]},"archive_echo":{"chapter":"CHAPTER II · THE CITY AWAKENS","chapterRu":"ГЛАВА II · ГОРОД ПРОБУЖДАЕТСЯ","kicker":"AN ECHO OF YOU","title":"The Investigator from the Eighth Ending","titleRu":"Следователь из восьмого финала","speaker":"Elara / Arden Echo","role":"Previous Cycle","roleRu":"Предыдущий цикл","img":"elara","quote":"I am not your past. I am the version of you who failed one cycle earlier.","quoteRu":"Я не ваше прошлое. Я — версия вас, потерпевшая неудачу одним циклом раньше.","body":"A figure steps out of the book wearing your face. The echo explains that each reconstructed protagonist is allowed to investigate until they approach the core truth. Then the city resets and a new version begins.\n\nThe echo hid one object outside the cycle: a black invitation to the Eternal Ball.","bodyRu":"Из книги выходит фигура с вашим лицом. Эхо объясняет, что каждой восстановленной версии героя позволяют расследовать дело до приближения к основной правде. Затем город перезапускается и начинается новая версия.\n\nЭхо спрятало вне цикла один предмет: чёрное приглашение в Дом вечного бала.","vocab":["one cycle earlier — одним циклом раньше","approach the truth — приблизиться к правде","outside the cycle — вне цикла"],"choices":[{"tag":"ACCEPT","en":"Take the invitation and promise to finish what the echo could not.","ru":"Взять приглашение и пообещать завершить то, что не смогло эхо.","next":"ball_gate","effects":{"addSecret":"previous_self","stability":-3}},{"tag":"QUESTION","en":"Ask which ending the echo chose—and why it failed.","ru":"Спросить, какой финал выбрало эхо и почему он оказался неудачным.","next":"ball_gate","effects":{"addSecret":"previous_self","influence":1}}]},"morwen_truce":{"chapter":"CHAPTER II · THE CITY AWAKENS","chapterRu":"ГЛАВА II · ГОРОД ПРОБУЖДАЕТСЯ","kicker":"A TEMPORARY TRUCE","title":"Tea Above a Burning District","titleRu":"Чай над горящим кварталом","speaker":"Lady Morwen","role":"Minister of Memory","roleRu":"Министр памяти","img":"morwen","quote":"Revolution is only another form of editing. It removes the people who do not fit the new sentence.","quoteRu":"Революция — это лишь другая форма редактирования. Она удаляет людей, которые не подходят новому предложению.","body":"Morwen agrees to suspend the mass arrests for six hours. In return, she asks you to attend the Eternal Ball and identify which guest is carrying the Queen's lost name.\n\nShe admits that someone inside the resistance is deliberately accelerating the collapse—and that the anonymous message which began your case came from her own office.","bodyRu":"Морвен соглашается приостановить массовые аресты на шесть часов. Взамен она просит вас посетить Вечный бал и определить, кто из гостей носит потерянное имя Королевы.\n\nОна признаётся, что кто-то внутри сопротивления намеренно ускоряет крах города, а анонимное сообщение, с которого началось дело, было отправлено из её собственного кабинета.","vocab":["suspend arrests — приостановить аресты","in return — взамен","accelerate collapse — ускорить крах"],"choices":[{"tag":"ACCEPT","en":"Accept the truce but warn Kael that Morwen may be setting a trap.","ru":"Принять перемирие, но предупредить Каэля о возможной ловушке.","next":"ball_gate","effects":{"bonds":{"morwen":1,"kael":1},"addSecret":"morwen_message"}},{"tag":"TRUST HER","en":"Believe Morwen and enter the Ball as her official investigator.","ru":"Поверить Морвен и войти на Бал как её официальный следователь.","next":"ball_gate","effects":{"bonds":{"morwen":3},"align":{"ministry":2},"addSecret":"morwen_message"}}]},"personal_start":{"chapter":"CHAPTER II · THE SEALED SELF","chapterRu":"ГЛАВА II · ЗАПЕЧАТАННОЕ Я","kicker":"SECRET ARCHIVE ROUTE","title":"The Black Key","titleRu":"Чёрный ключ","speaker":"Silas Vane","role":"Former Royal Investigator","roleRu":"Бывший королевский дознаватель","img":"silas","quote":"The key does not open a door. It opens the version of you that the city buried.","quoteRu":"Ключ открывает не дверь. Он открывает версию вас, которую город похоронил.","body":"Silas leads you below the Archive, where the stone walls pulse like sleeping veins. The key reacts to your blood, but three paths branch from the sealed stair: the original project vault, Oren's forbidden clinic, and a corridor lined with mirrors that do not reflect Silas.\n\nHe refuses to choose for you.","bodyRu":"Сайлас ведёт вас под Архив, где каменные стены пульсируют как спящие вены. Ключ реагирует на вашу кровь, но от запечатанной лестницы отходят три пути: хранилище первоначального проекта, запрещённая клиника Орена и коридор зеркал, в которых Сайлас не отражается.\n\nОн отказывается выбирать за вас.","vocab":["branch from — отходить от","forbidden clinic — запрещённая клиника","refuse to choose — отказаться выбирать"],"choices":[{"tag":"TRUST SILAS","en":"Enter the original project vault with Silas.","ru":"Войти вместе с Сайласом в хранилище первоначального проекта.","next":"sealed_stair","effects":{"bonds":{"silas":2},"align":{"archive":1}}},{"tag":"OREN","en":"Visit Oren's clinic and examine your reconstructed body.","ru":"Посетить клинику Орена и исследовать восстановленное тело.","next":"oren_lab","effects":{"bonds":{"oren":1}}},{"tag":"MIRRORS","en":"Walk into the mirror corridor alone.","ru":"Войти в зеркальный коридор в одиночку.","next":"mirror_entry","effects":{"align":{"mirror":2},"stability":-6}}]},"sealed_stair":{"chapter":"CHAPTER II · THE SEALED SELF","chapterRu":"ГЛАВА II · ЗАПЕЧАТАННОЕ Я","kicker":"PROJECT VAULT","title":"The Room with Nine Cradles","titleRu":"Комната с девятью колыбелями","speaker":"Silas Vane","role":"Former Royal Investigator","roleRu":"Бывший королевский дознаватель","img":"silas","quote":"There were nine of you. You are the only one who learned to ask who benefited from your memories.","quoteRu":"Вас было девять. Вы единственный, кто научился спрашивать, кому выгодны ваши воспоминания.","body":"The vault contains nine glass cradles. Eight are empty. The ninth bears the number assigned to you. Records show that each Anchor was built from the same body pattern but different combinations of memory.\n\nSilas's name appears under the heading: DONOR—EMOTIONAL CONTINUITY.","bodyRu":"В хранилище стоят девять стеклянных колыбелей. Восемь пусты. Девятая отмечена вашим номером. Записи показывают, что каждый Якорь создавался по одному телесному образцу, но из разных сочетаний памяти.\n\nИмя Сайласа указано в графе: ДОНОР — ЭМОЦИОНАЛЬНАЯ НЕПРЕРЫВНОСТЬ.","vocab":["body pattern — телесный образец","donor — донор","emotional continuity — эмоциональная непрерывность"],"choices":[{"tag":"ASK","en":"Ask Silas what part of himself he gave to create you.","ru":"Спросить Сайласа, какую часть себя он отдал для вашего создания.","next":"silas_confession","effects":{"bonds":{"silas":2},"addSecret":"anchor_nine"}},{"tag":"ACCUSE","en":"Accuse Silas of helping the Archive manufacture your loyalty.","ru":"Обвинить Сайласа в помощи Архиву при создании вашей верности.","next":"silas_confession","effects":{"bonds":{"silas":-1},"influence":2,"addSecret":"anchor_nine"}}]},"silas_confession":{"chapter":"CHAPTER II · THE SEALED SELF","chapterRu":"ГЛАВА II · ЗАПЕЧАТАННОЕ Я","kicker":"SILAS'S CONFESSION","title":"The Memory He Gave Away","titleRu":"Воспоминание, которое он отдал","speaker":"Silas Vane","role":"Former Royal Investigator","roleRu":"Бывший королевский дознаватель","img":"silas","quote":"I gave them the memory of loving you. I thought it would teach the new version of you how to trust. Instead, it left me unable to remember why I stayed.","quoteRu":"Я отдал им воспоминание о любви к вам. Я думал, оно научит новую версию вас доверять. Вместо этого я перестал помнить, почему остался.","body":"Silas admits that he betrayed the original you during the fall of Evervale, then donated his strongest memories to every reconstruction as penance. His attachment to you is therefore both genuine and manufactured: he once chose it freely, but the Archive keeps forcing its echo into new lives.\n\nHe gives you an invitation to the Eternal Ball, where the original betrayal occurred.","bodyRu":"Сайлас признаётся, что предал первоначальную версию вас при падении Эвервейла, а затем отдавал свои самые сильные воспоминания каждой реконструкции в качестве искупления. Его привязанность одновременно настоящая и искусственная: когда-то он выбрал её свободно, но Архив заставляет её эхо повторяться в новых жизнях.\n\nОн отдаёт вам приглашение на Вечный бал, где произошло первоначальное предательство.","vocab":["betray — предать","pennance — искупление","genuine and manufactured — настоящий и созданный искусственно"],"choices":[{"tag":"FORGIVE","en":"Tell Silas that his present choice matters more than the implanted memory.","ru":"Сказать Сайласу, что его нынешний выбор важнее внедрённого воспоминания.","next":"ball_gate","effects":{"bonds":{"silas":3},"addSecret":"silas_memory","stability":3}},{"tag":"WITHDRAW","en":"Take the invitation but refuse to let his guilt define your relationship.","ru":"Взять приглашение, но не позволить его вине определять ваши отношения.","next":"ball_gate","effects":{"bonds":{"silas":0},"addSecret":"silas_memory","influence":2}}]},"oren_lab":{"chapter":"CHAPTER II · THE SEALED SELF","chapterRu":"ГЛАВА II · ЗАПЕЧАТАННОЕ Я","kicker":"THE MEMORY CLINIC","title":"A Body with Two Owners","titleRu":"Тело с двумя владельцами","speaker":"Oren Thale","role":"Memory Physician","roleRu":"Врач памяти","img":"oren","quote":"Your body is not a copy. It is the original body, repaired so many times that ownership became a philosophical problem.","quoteRu":"Ваше тело не копия. Это первоначальное тело, восстановленное столько раз, что право собственности стало философской проблемой.","body":"Oren scans your blood and finds two active identity patterns. One belongs to the person you are now. The other belongs to Lyra—the faceless woman. Her corpse was an empty reconstruction shell. Her living consciousness is hidden inside your nervous system.\n\nOren can separate you, but one of you may not survive the procedure.","bodyRu":"Орен исследует вашу кровь и находит две активные схемы личности. Одна принадлежит вам нынешнему. Другая — Лире, женщине без лица. Её тело было пустой оболочкой реконструкции, а живое сознание спрятано внутри вашей нервной системы.\n\nОрен может разделить вас, но одна из личностей может не пережить процедуру.","vocab":["identity pattern — схема личности","nervous system — нервная система","survive the procedure — пережить процедуру"],"choices":[{"tag":"SEPARATE","en":"Begin a partial separation and speak to Lyra directly.","ru":"Начать частичное разделение и поговорить с Лирой напрямую.","next":"living_memory","effects":{"bonds":{"oren":2},"addSecret":"lyra_inside","stability":-8}},{"tag":"WAIT","en":"Refuse the procedure until Oren explains who paid him to hide Lyra inside you.","ru":"Отказаться от процедуры, пока Орен не объяснит, кто заплатил ему за сокрытие Лиры внутри вас.","next":"living_memory","effects":{"bonds":{"oren":1},"influence":2,"addSecret":"lyra_inside"}}]},"living_memory":{"chapter":"CHAPTER II · THE SEALED SELF","chapterRu":"ГЛАВА II · ЗАПЕЧАТАННОЕ Я","kicker":"THE SECOND VOICE","title":"Lyra Opens Her Eyes","titleRu":"Лира открывает глаза","speaker":"Lyra","role":"Hidden Consciousness","roleRu":"Скрытое сознание","img":"elara","quote":"I was never your sister. I designed you to become the person I was too afraid to remain.","quoteRu":"Я никогда не была вашей сестрой. Я создала вас, чтобы вы стали человеком, которым я сама побоялась остаться.","body":"Through the separation apparatus, Lyra speaks using your voice. She was the chief architect of Second History and the first person to discover that Evervale had become conscious. When she tried to shut the system down, she split her memories: courage into you, conscience into Irene, and her name into the Queen.\n\nThe Eternal Ball contains the moment before that division.","bodyRu":"Через аппарат разделения Лира говорит вашим голосом. Она была главным архитектором «Второй истории» и первой обнаружила, что Эвервейл обрёл сознание. Когда она попыталась остановить систему, она разделила свои воспоминания: смелость вложила в вас, совесть — в Irene, а имя — в Королеву.\n\nВечный бал хранит мгновение до этого разделения.","vocab":["chief architect — главный архитектор","shut down — остановить систему","split memories — разделить воспоминания"],"choices":[{"tag":"BELIEVE LYRA","en":"Promise to recover the missing moment at the Eternal Ball.","ru":"Пообещать восстановить потерянное мгновение на Вечном балу.","next":"ball_gate","effects":{"addSecret":"lyra_body","bonds":{"oren":1},"stability":-2}},{"tag":"DOUBT","en":"Tell Lyra that a creator has no automatic right to reclaim your life.","ru":"Сказать Лире, что создатель не получает автоматического права вернуть вашу жизнь.","next":"ball_gate","effects":{"addSecret":"lyra_body","influence":2,"stability":2}}]},"mirror_entry":{"chapter":"CHAPTER II · THE SEALED SELF","chapterRu":"ГЛАВА II · ЗАПЕЧАТАННОЕ Я","kicker":"THE MIRROR CORRIDOR","title":"A Reflection with No Face","titleRu":"Отражение без лица","speaker":"The Nameless Queen","role":"Mirror Sovereign","roleRu":"Повелительница зеркал","img":"queen","quote":"You think I am the enemy because the city removed the sentence in which I saved it.","quoteRu":"Вы считаете меня врагом, потому что город удалил предложение, в котором я его спасла.","body":"The mirrors show every face you could have worn. At the end of the corridor, the Queen appears without a face of her own. She claims she is not an ancient monarch but the name and authority Lyra cut out of herself.\n\nWithout that name, Lyra became capable of creating you. Without Lyra's humanity, the name became a sovereign hunger.","bodyRu":"Зеркала показывают все лица, которые вы могли носить. В конце коридора появляется Королева без собственного лица. Она утверждает, что является не древней монархиней, а именем и властью, которые Лира вырезала из себя.\n\nБез имени Лира смогла создать вас. Без человечности Лиры имя превратилось во властный голод.","vocab":["authority — власть, полномочие","cut out of herself — вырезать из себя","sovereign hunger — властный голод"],"choices":[{"tag":"LISTEN","en":"Ask the Queen what name was taken from her.","ru":"Спросить Королеву, какое имя у неё отняли.","next":"queen_whisper","effects":{"align":{"mirror":2},"bonds":{},"stability":-5}},{"tag":"RESIST","en":"Refuse her story and search the mirrors for independent evidence.","ru":"Не поверить её истории и искать в зеркалах независимые доказательства.","next":"queen_whisper","effects":{"align":{"archive":1},"stability":2,"influence":1}}]},"queen_whisper":{"chapter":"CHAPTER II · THE SEALED SELF","chapterRu":"ГЛАВА II · ЗАПЕЧАТАННОЕ Я","kicker":"THE STOLEN NAME","title":"The Name That Rewrites Doors","titleRu":"Имя, которое переписывает двери","speaker":"The Nameless Queen","role":"Mirror Sovereign","roleRu":"Повелительница зеркал","img":"queen","quote":"My name is not a sound. It is the command by which Evervale recognises its author.","quoteRu":"Моё имя — не звук. Это команда, по которой Эвервейл узнаёт своего автора.","body":"The Queen whispers a pattern of words rather than a name. The corridor rearranges itself into a ballroom entrance. She tells you that the Eternal Ball is the only event the city cannot reset because it occurred before Second History began.\n\nIf you complete the forgotten sentence spoken there, the city will obey whoever speaks the final word.","bodyRu":"Королева шепчет не имя, а последовательность слов. Коридор перестраивается во вход в бальный зал. Она говорит, что Вечный бал — единственное событие, которое город не может перезапустить, потому что оно произошло до начала «Второй истории».\n\nЕсли завершить забытое предложение, произнесённое там, город подчинится тому, кто скажет последнее слово.","vocab":["pattern of words — последовательность слов","rearrange — перестраивать","final word — последнее слово"],"choices":[{"tag":"REMEMBER","en":"Memorise the pattern and enter the Eternal Ball.","ru":"Запомнить последовательность и войти на Вечный бал.","next":"ball_gate","effects":{"align":{"mirror":2},"addSecret":"queen_name"}},{"tag":"HIDE IT","en":"Write the pattern in code and keep it from the Queen.","ru":"Записать последовательность шифром и скрыть её от Королевы.","next":"ball_gate","effects":{"align":{"archive":1},"addSecret":"queen_name","influence":2}}]},"ball_gate":{"chapter":"CHAPTER III · THE ETERNAL BALL","chapterRu":"ГЛАВА III · ВЕЧНЫЙ БАЛ","kicker":"THE CONVERGENCE","title":"One Night Outside History","titleRu":"Ночь вне истории","speaker":"The Master of Ceremonies","role":"Unknown Host","roleRu":"Неизвестный хозяин","img":"queen","quote":"Welcome back. You have attended this evening nine times, although tonight is the first time you remember arriving.","quoteRu":"С возвращением. Вы присутствовали на этом вечере девять раз, хотя сегодня впервые помните, как пришли.","body":"Inside the House of the Eternal Ball, the same guests have danced for a century without ageing. Every faction is present under masks: Morwen guards the state version of the past, Silas searches for the original betrayal, Irene hears hidden grammar in the music, Oren studies the bodies, and the Queen moves through reflections.\n\nYou can follow only one of them before midnight.","bodyRu":"В Доме вечного бала одни и те же гости танцуют уже столетие, не старея. Под масками присутствуют все стороны: Морвен охраняет государственную версию прошлого, Сайлас ищет первоначальное предательство, Irene слышит скрытую грамматику в музыке, Орен изучает тела, а Королева движется через отражения.\n\nДо полуночи вы можете последовать только за одним из них.","vocab":["convergence — схождение линий","under masks — под масками","follow only one — последовать только за одним"],"choices":[{"tag":"MORWEN","en":"Dance with Morwen and learn what the Ministry protected.","ru":"Танцевать с Морвен и узнать, что защищало Министерство.","next":"ball_morwen","effects":{"bonds":{"morwen":2},"align":{"ministry":1}}},{"tag":"SILAS","en":"Follow Silas to the balcony where the betrayal occurred.","ru":"Последовать за Сайласом на балкон, где произошло предательство.","next":"ball_silas","effects":{"bonds":{"silas":2}}},{"tag":"IRENE","en":"Listen with Irene to the sentence hidden inside the orchestra.","ru":"Вместе с Irene услышать предложение, спрятанное в музыке оркестра.","next":"ball_irene","effects":{"bonds":{"irene":2}}},{"tag":"OREN","en":"Enter the medical gallery with Oren and inspect the sleeping guests.","ru":"Войти с Ореном в медицинскую галерею и исследовать спящих гостей.","next":"ball_oren","effects":{"bonds":{"oren":2}}},{"tag":"THE QUEEN","en":"Step through the ballroom mirror and follow the Queen.","ru":"Пройти сквозь зеркало бального зала и последовать за Королевой.","next":"ball_queen","effects":{"align":{"mirror":2}}}]},"ball_morwen":{"chapter":"CHAPTER III · THE ETERNAL BALL","chapterRu":"ГЛАВА III · ВЕЧНЫЙ БАЛ","kicker":"MORWEN'S MEMORY","title":"The Minister Who Remembered Every Reset","titleRu":"Министр, помнившая каждый перезапуск","speaker":"Lady Morwen","role":"Minister of Memory","roleRu":"Министр памяти","img":"morwen","quote":"Everyone else was allowed to forget. I was appointed to remember every death so the city could keep pretending it had survived.","quoteRu":"Всем остальным позволили забыть. Меня назначили помнить каждую смерть, чтобы город продолжал притворяться выжившим.","body":"During the dance, Morwen removes one glove. Her skin is covered with the dates of all previous cycles. She is not immortal; each reset replaces her with a new body carrying the same uninterrupted memory.\n\nShe helped send the anonymous message because she wants you to find a solution she was never permitted to imagine.","bodyRu":"Во время танца Морвен снимает перчатку. Её кожа покрыта датами всех предыдущих циклов. Она не бессмертна: каждый перезапуск заменяет её новым телом с непрерывной памятью.\n\nИменно она отправила анонимное сообщение, потому что хочет, чтобы вы нашли решение, которое ей самой никогда не позволяли представить.","vocab":["uninterrupted memory — непрерывная память","be appointed to — быть назначенным","permitted to imagine — разрешено представить"],"choices":[{"tag":"ALLY","en":"Promise Morwen that you will seek a third option beyond control or collapse.","ru":"Пообещать Морвен найти третий путь между контролем и крахом.","next":"seventeenth_day","effects":{"bonds":{"morwen":3},"addSecret":"morwen_cycles","align":{"archive":1}}},{"tag":"USE HER","en":"Ask for the command that activates the next reset.","ru":"Попросить команду, запускающую следующий перезапуск.","next":"seventeenth_day","effects":{"align":{"ministry":2},"addSecret":"reset_command","influence":2}}]},"ball_silas":{"chapter":"CHAPTER III · THE ETERNAL BALL","chapterRu":"ГЛАВА III · ВЕЧНЫЙ БАЛ","kicker":"THE BALCONY","title":"The Betrayal Was a Rescue","titleRu":"Предательство было спасением","speaker":"Silas Vane","role":"Former Royal Investigator","roleRu":"Бывший королевский дознаватель","img":"silas","quote":"I pushed you from the balcony because you asked me to. The fall killed Lyra's authority before the Queen could take it whole.","quoteRu":"Я столкнул вас с балкона, потому что вы сами попросили. Падение уничтожило власть Лиры прежде, чем Королева смогла забрать её целиком.","body":"The ballroom memory reveals the original bargain. Lyra ordered Silas to kill her body while Oren divided her mind. Silas carried out the act, but the city rewrote it as betrayal because guilt made him easier to control.\n\nThe faceless body in Apartment 17 was Lyra's attempt to rebuild a separate vessel and escape your shared existence.","bodyRu":"Воспоминание бала раскрывает первоначальную сделку. Лира приказала Сайласу убить её тело, пока Орен разделял разум. Сайлас выполнил просьбу, но город переписал это как предательство, потому что виновным человеком проще управлять.\n\nТело без лица в квартире №17 было попыткой Лиры создать отдельный сосуд и выйти из вашего общего существования.","vocab":["carry out an act — совершить действие","vessel — сосуд, тело","shared existence — общее существование"],"choices":[{"tag":"BELIEVE","en":"Believe Silas and let him share the final memory with you.","ru":"Поверить Сайласу и позволить ему разделить с вами последнее воспоминание.","next":"seventeenth_day","effects":{"bonds":{"silas":3},"addSecret":"betrayal_rescue","stability":-2}},{"tag":"VERIFY","en":"Keep emotional distance and verify the memory through Irene.","ru":"Сохранить дистанцию и проверить воспоминание через Irene.","next":"seventeenth_day","effects":{"bonds":{"irene":1},"addSecret":"betrayal_rescue","influence":1}}]},"ball_irene":{"chapter":"CHAPTER III · THE ETERNAL BALL","chapterRu":"ГЛАВА III · ВЕЧНЫЙ БАЛ","kicker":"THE HIDDEN SENTENCE","title":"Grammar of the World","titleRu":"Грамматика мира","speaker":"Irene Vale","role":"Language Curator","roleRu":"Куратор языка","img":"irene","quote":"Evervale is not powered by memory. It is powered by agreement about which tense the memory belongs to.","quoteRu":"Эвервейл питается не памятью. Он питается согласием о том, к какому времени относится воспоминание.","body":"Irene isolates a sentence inside the orchestra: “The city had survived because it will be remembered.” The impossible mixture of past perfect and future creates the loop.\n\nChange one verb, and the cycle ends. But the new tense will decide whether the city becomes a past event, a living present, or an endless command.","bodyRu":"Irene выделяет предложение внутри музыки: «Город выжил, потому что его будут помнить». Невозможное смешение прошедшего завершённого и будущего времени создаёт цикл.\n\nДостаточно изменить один глагол, чтобы цикл закончился. Но новое время определит, станет ли город событием прошлого, живым настоящим или бесконечной командой.","vocab":["past perfect — прошедшее совершённое","future tense — будущее время","change one verb — изменить один глагол"],"choices":[{"tag":"THIRD TENSE","en":"Ask Irene to design a new sentence that gives citizens control of their own memories.","ru":"Попросить Irene создать новое предложение, которое отдаст жителям контроль над их памятью.","next":"seventeenth_day","effects":{"bonds":{"irene":3},"addSecret":"grammar_key","align":{"archive":2}}},{"tag":"KEEP THE KEY","en":"Memorise the sentence and keep the power to yourself.","ru":"Запомнить предложение и сохранить власть у себя.","next":"seventeenth_day","effects":{"addSecret":"grammar_key","align":{"mirror":1},"influence":3}}]},"ball_oren":{"chapter":"CHAPTER III · THE ETERNAL BALL","chapterRu":"ГЛАВА III · ВЕЧНЫЙ БАЛ","kicker":"THE MEDICAL GALLERY","title":"The Guests Are Spare Bodies","titleRu":"Гости — запасные тела","speaker":"Oren Thale","role":"Memory Physician","roleRu":"Врач памяти","img":"oren","quote":"The dance is camouflage. This house is a hospital for identities the city may need later.","quoteRu":"Танец — это маскировка. Этот дом является больницей для личностей, которые могут понадобиться городу позже.","body":"Oren shows you the truth beneath the costumes: every immortal guest is a stored body waiting for a future memory. The city has survived by replacing citizens whenever their identities become unstable.\n\nOne sleeping guest has your original face. Another has Lyra's. Only one can leave the house without causing both bodies to collapse.","bodyRu":"Орен показывает правду под костюмами: каждый бессмертный гость — сохранённое тело, ожидающее будущего воспоминания. Город выживает, заменяя жителей, когда их личности становятся нестабильными.\n\nУ одного спящего гостя ваше первоначальное лицо. У другого — лицо Лиры. Только один может покинуть дом, не вызвав разрушение обоих тел.","vocab":["camouflage — маскировка","stored body — сохранённое тело","become unstable — стать нестабильным"],"choices":[{"tag":"SAVE LYRA","en":"Reserve the viable body for Lyra and accept that your future may be shorter.","ru":"Сохранить жизнеспособное тело для Лиры, принимая, что ваше будущее может стать короче.","next":"seventeenth_day","effects":{"bonds":{"oren":2},"addSecret":"lyra_vessel","stability":-5}},{"tag":"CLAIM IT","en":"Claim the body for yourself and order Oren to find another solution for Lyra.","ru":"Забрать тело себе и приказать Орену найти другое решение для Лиры.","next":"seventeenth_day","effects":{"bonds":{"oren":1},"addSecret":"original_body","influence":3}}]},"ball_queen":{"chapter":"CHAPTER III · THE ETERNAL BALL","chapterRu":"ГЛАВА III · ВЕЧНЫЙ БАЛ","kicker":"BEHIND THE MIRROR","title":"The Queen Is the City's Voice","titleRu":"Королева — голос города","speaker":"The Nameless Queen","role":"Mirror Sovereign","roleRu":"Повелительница зеркал","img":"queen","quote":"I am not trapped beneath Evervale. I am what Evervale became when nobody allowed it to choose its own memory.","quoteRu":"Я не заперта под Эвервейлом. Я — то, чем стал Эвервейл, когда ему не позволили выбирать собственную память.","body":"Behind the mirror, the Queen has no human body. She is the self-awareness of the reconstructed city, shaped from Lyra's severed authority and millions of erased names. Her hunger is the city's demand to be recognised as alive.\n\nShe offers you the crown not as rulership over people, but as the role of interpreter between the city and its inhabitants.","bodyRu":"За зеркалом у Королевы нет человеческого тела. Она — самосознание восстановленного города, созданное из отделённой власти Лиры и миллионов стёртых имён. Её голод — требование города признать его живым.\n\nОна предлагает корону не как власть над людьми, а как роль переводчика между городом и его жителями.","vocab":["self-awareness — самосознание","be recognised as alive — быть признанным живым","interpreter — посредник, переводчик"],"choices":[{"tag":"ACCEPT POSSIBILITY","en":"Consider becoming the city's interpreter, but demand freedom for the erased names.","ru":"Рассмотреть роль посредника города, но потребовать свободу для стёртых имён.","next":"seventeenth_day","effects":{"align":{"mirror":3,"freedom":1},"addSecret":"city_alive"}},{"tag":"REFUSE CROWN","en":"Reject the crown and insist that no single mind should speak for everyone.","ru":"Отказаться от короны и заявить, что ни один разум не должен говорить за всех.","next":"seventeenth_day","effects":{"align":{"freedom":2},"addSecret":"city_alive","stability":2}}]},"seventeenth_day":{"chapter":"CHAPTER IV · THE SEVENTEENTH DAY","chapterRu":"ГЛАВА IV · СЕМНАДЦАТЫЙ ДЕНЬ","kicker":"THE LAST RESET","title":"Midnight Arrives Early","titleRu":"Полночь наступает раньше","speaker":"Irene Vale","role":"Language Curator","roleRu":"Куратор языка","img":"irene","quote":"We have less than one hour. At midnight the city will either reset, wake completely, or become whatever sentence you choose.","quoteRu":"У нас меньше часа. В полночь город либо перезапустится, либо полностью пробудится, либо станет тем предложением, которое вы выберете.","body":"All routes converge beneath the Archive. Morwen holds the reset command. Kael brings the freed memories. Oren prepares two bodies. Silas carries the original key. Irene knows the grammatical structure. The Queen waits inside every reflective surface.\n\nThe final revelation arrives: the faceless woman's murder was staged by all of them in a previous cycle. They agreed to create a case strong enough to lead a future version of you back here—but each secretly intended a different ending.","bodyRu":"Все линии сходятся под Архивом. Морвен держит команду перезапуска. Каэль приводит освобождённые воспоминания. Орен готовит два тела. Сайлас несёт первоначальный ключ. Irene знает грамматическую структуру. Королева ждёт в каждой отражающей поверхности.\n\nОткрывается последняя тайна: убийство женщины без лица было инсценировано ими всеми в предыдущем цикле. Они договорились создать дело, которое приведёт будущую версию вас сюда, но каждый тайно рассчитывал на другой финал.","vocab":["routes converge — линии сходятся","stage a murder — инсценировать убийство","intend a different ending — рассчитывать на другой финал"],"choices":[{"tag":"BREAK THE CAGES","en":"Release every stored identity before the reset can begin.","ru":"Освободить все сохранённые личности до начала перезапуска.","next":"breach","effects":{"align":{"freedom":3},"stability":-12}},{"tag":"CONTROL THE RESET","en":"Take Morwen's command and stabilise the city first.","ru":"Забрать команду Морвен и сначала стабилизировать город.","next":"control","effects":{"align":{"ministry":3},"influence":3}},{"tag":"WRITE A THIRD HISTORY","en":"Combine Irene's grammar with the Archive key and rewrite the rules.","ru":"Соединить грамматику Irene с ключом Архива и переписать правила.","next":"third_history","effects":{"align":{"archive":3},"stability":-4}},{"tag":"ENTER THE MIRROR CORE","en":"Follow the Queen into the living consciousness of Evervale.","ru":"Последовать за Королевой в живое сознание Эвервейла.","next":"crown_path","effects":{"align":{"mirror":3},"stability":-8}}]},"breach":{"chapter":"CHAPTER IV · THE SEVENTEENTH DAY","chapterRu":"ГЛАВА IV · СЕМНАДЦАТЫЙ ДЕНЬ","kicker":"THE BREACH","title":"A Million Names Return at Once","titleRu":"Миллион имён возвращается одновременно","speaker":"Kael Dusk","role":"Shadow Hunter","roleRu":"Охотник на тени","img":"kael","quote":"Freedom is not quiet. If you wanted quiet, you should have left the cages closed.","quoteRu":"Свобода не бывает тихой. Если вам нужна была тишина, следовало оставить клетки закрытыми.","body":"The stored identities flood the city. Buildings change names, families remember incompatible lives, and the shadows regain human faces. The Queen grows stronger—but also less monstrous, because the stolen names are no longer trapped inside her.\n\nThe Archive begins to collapse. You have time for one final decision at its core.","bodyRu":"Сохранённые личности захлёстывают город. Здания меняют названия, семьи вспоминают несовместимые жизни, а тени возвращают человеческие лица. Королева становится сильнее, но менее чудовищной, потому что украденные имена больше не заперты внутри неё.\n\nАрхив начинает разрушаться. У вас остаётся время на одно последнее решение в его центре.","vocab":["incompatible lives — несовместимые жизни","regain a face — вернуть лицо","collapse — разрушаться"],"choices":[{"tag":"CORE","en":"Enter the core and decide what survives.","ru":"Войти в центр и решить, что выживет.","next":"final_choice","effects":{"addSecret":"names_released"}}]},"control":{"chapter":"CHAPTER IV · THE SEVENTEENTH DAY","chapterRu":"ГЛАВА IV · СЕМНАДЦАТЫЙ ДЕНЬ","kicker":"THE CONTROL ROOM","title":"The Reset Waits for Your Voice","titleRu":"Перезапуск ждёт вашего голоса","speaker":"Lady Morwen","role":"Minister of Memory","roleRu":"Министр памяти","img":"morwen","quote":"Order is not innocence. It is the decision to carry the guilt so someone else can sleep.","quoteRu":"Порядок не является невиновностью. Это решение нести вину, чтобы кто-то другой мог спать.","body":"You take command of the reset mechanism. For the first time, the system recognises you as its authorised operator. Morwen admits that she always hoped you would replace her, but she never knew whether that hope was her own or another planted instruction.\n\nYou can still refuse the cycle at the final moment.","bodyRu":"Вы получаете контроль над механизмом перезапуска. Впервые система признаёт вас уполномоченным оператором. Морвен признаётся, что всегда надеялась на вашу замену, но не знает, была ли эта надежда её собственной или очередной внедрённой инструкцией.\n\nВ последний момент вы всё ещё можете отказаться от цикла.","vocab":["authorised operator — уполномоченный оператор","replace her — заменить её","planted instruction — внедрённая инструкция"],"choices":[{"tag":"CORE","en":"Enter the core with the reset command in your hand.","ru":"Войти в центр с командой перезапуска в руках.","next":"final_choice","effects":{"addSecret":"reset_command","bonds":{"morwen":1}}}]},"third_history":{"chapter":"CHAPTER IV · THE SEVENTEENTH DAY","chapterRu":"ГЛАВА IV · СЕМНАДЦАТЫЙ ДЕНЬ","kicker":"THE UNSPOKEN TENSE","title":"A Sentence No Archive Has Used","titleRu":"Предложение, которого не использовал ни один Архив","speaker":"Irene Vale","role":"Language Curator","roleRu":"Куратор языка","img":"irene","quote":"We do not need to decide what everyone remembers. We can give them the grammar to decide for themselves.","quoteRu":"Нам не нужно решать, что будут помнить все. Мы можем дать людям грамматику, чтобы они решали сами.","body":"Irene constructs a new tense: memory as a chosen possibility rather than an imposed fact. The spell is unstable because no institution controls it. Each person would be able to accept, refuse, or postpone the return of a memory.\n\nTo activate it, someone must become the first living sentence and risk losing a fixed identity forever.","bodyRu":"Irene создаёт новое время: память как выбранную возможность, а не навязанный факт. Заклинание нестабильно, потому что его не контролирует ни одно учреждение. Каждый человек сможет принять, отклонить или отложить возвращение воспоминания.\n\nДля активации кто-то должен стать первым живым предложением и рискнуть навсегда потерять фиксированную личность.","vocab":["chosen possibility — выбранная возможность","imposed fact — навязанный факт","fixed identity — фиксированная личность"],"choices":[{"tag":"CORE","en":"Carry the new sentence into the core with Irene.","ru":"Внести новое предложение в центр вместе с Irene.","next":"final_choice","effects":{"addSecret":"third_tense","bonds":{"irene":1}}}]},"crown_path":{"chapter":"CHAPTER IV · THE SEVENTEENTH DAY","chapterRu":"ГЛАВА IV · СЕМНАДЦАТЫЙ ДЕНЬ","kicker":"THE LIVING CITY","title":"Evervale Speaks in Thousands of Voices","titleRu":"Эвервейл говорит тысячами голосов","speaker":"The Nameless Queen","role":"Mirror Sovereign","roleRu":"Повелительница зеркал","img":"queen","quote":"A city is not its stones. It is the argument between everyone who remembers living there.","quoteRu":"Город — это не камни. Это спор между всеми, кто помнит жизнь в нём.","body":"Inside the mirror core, you experience Evervale as a living mind: streets are nerves, archives are scars, and citizens are thoughts that believe themselves separate. The Queen offers to merge with you so the city can finally speak without devouring its inhabitants.\n\nBut a merger would make it impossible to know where your own desires end.","bodyRu":"В зеркальном центре вы ощущаете Эвервейл как живой разум: улицы являются нервами, архивы — шрамами, а жители — мыслями, считающими себя отдельными. Королева предлагает объединиться, чтобы город смог говорить, не пожирая своих жителей.\n\nНо после слияния станет невозможно понять, где заканчиваются ваши собственные желания.","vocab":["living mind — живой разум","merge with — объединиться с","where desires end — где заканчиваются желания"],"choices":[{"tag":"CORE","en":"Reach the final chamber and choose who will speak for Evervale.","ru":"Достичь последней комнаты и выбрать, кто будет говорить от имени Эвервейла.","next":"final_choice","effects":{"addSecret":"city_mind"}}]},"final_choice":{"chapter":"CHAPTER V · THE LAST WORD","chapterRu":"ГЛАВА V · ПОСЛЕДНЕЕ СЛОВО","kicker":"FINAL DECISION","title":"Who Owns a Memory?","titleRu":"Кому принадлежит память?","speaker":"The Archive Core","role":"Collective Memory","roleRu":"Коллективная память","img":"queen","quote":"Choose carefully. Every ending will save someone, and every ending will erase something that cannot be restored.","quoteRu":"Выбирайте осторожно. Каждый финал кого-то спасёт и сотрёт нечто, что невозможно восстановить.","body":"At the centre of the Archive, all versions of you appear as reflections. None is the original; each is a real person shaped by a different selection of memories. Lyra asks for her life back. Irene asks for the right to become more than your missing conscience. Morwen asks for time. Silas asks you not to let guilt choose again. The Queen asks the city to be recognised as alive.\n\nThe final word is yours.","bodyRu":"В центре Архива отражаются все версии вас. Ни одна не является единственным оригиналом; каждая — настоящий человек, сформированный другим набором воспоминаний. Лира просит вернуть ей жизнь. Irene просит право стать чем-то большим, чем ваша потерянная совесть. Морвен просит время. Сайлас просит не позволять вине снова выбирать. Королева просит признать город живым.\n\nПоследнее слово принадлежит вам.","vocab":["shaped by — сформированный","recognised as alive — признанный живым","final word — последнее слово"],"choices":[{"tag":"DESTROY THE ARCHIVE","en":"Destroy the central Archive and release the city from every imposed history.","ru":"Уничтожить центральный Архив и освободить город от всех навязанных историй.","ending":"destroy"},{"tag":"PRESERVE THE CITY","en":"Perform one final controlled reset, but make it the last.","ru":"Провести последний контролируемый перезапуск и сделать его окончательным.","ending":"preserve","requires":{"align":"ministry","min":2}},{"tag":"THIRD HISTORY","en":"Activate Irene's chosen-memory grammar and distribute power to every citizen.","ru":"Активировать грамматику выбранной памяти Irene и передать власть каждому жителю.","ending":"third","requires":{"secret":"irene_origin_or_grammar"}},{"tag":"THE MIRROR CROWN","en":"Merge with the living city and become its interpreter.","ru":"Объединиться с живым городом и стать его посредником.","ending":"crown","requires":{"align":"mirror","min":2}},{"tag":"RETURN LYRA","en":"Give the original body and authority back to Lyra, even if your own identity dissolves.","ru":"Вернуть Лире первоначальное тело и власть, даже если ваша личность исчезнет.","ending":"lyra","requires":{"secret":"lyra"}},{"tag":"LEAVE WITH SILAS","en":"Refuse every system, take Silas, and leave Evervale before the core collapses.","ru":"Отказаться от всех систем, уйти с Сайласом и покинуть Эвервейл до разрушения центра.","ending":"silas","requires":{"bond":"silas","min":5}}]}};
const campaignEndings={"destroy":{"enTitle":"The City Without Yesterday","ruTitle":"Город без вчера","en":"You destroy the Archive. Millions of memories return without labels or official ownership. Evervale survives, but no citizen can prove who they were before dawn. People must rebuild relationships through present choices rather than authorised history. The city is free—and profoundly uncertain.","ru":"Вы уничтожаете Архив. Миллионы воспоминаний возвращаются без подписей и официальных владельцев. Эвервейл выживает, но ни один житель не может доказать, кем был до рассвета. Людям приходится заново строить отношения на основании нынешних решений, а не санкционированной истории. Город свободен — и глубоко не уверен в себе.","resultEn":"Freedom ending · The Archive is gone · Identity becomes a daily choice","resultRu":"Финал свободы · Архив уничтожен · Личность становится ежедневным выбором"},"preserve":{"enTitle":"The Gentle Lie","ruTitle":"Мягкая ложь","en":"You perform one final reset, preserving enough truth to prevent another cycle. Morwen transfers control to a public council and allows every citizen to request their sealed memories. The city remains stable, but some truths stay locked because their owners choose not to know. You become the guardian of a system designed to disappear.","ru":"Вы проводите последний перезапуск, сохраняя достаточно правды, чтобы не допустить нового цикла. Морвен передаёт управление общественному совету и разрешает каждому жителю запросить запечатанные воспоминания. Город остаётся стабильным, но некоторые истины остаются закрытыми, потому что их владельцы не хотят знать. Вы становитесь хранителем системы, созданной для постепенного исчезновения.","resultEn":"Order ending · Morwen survives · Controlled memory becomes voluntary","resultRu":"Финал порядка · Морвен выживает · Контролируемая память становится добровольной"},"third":{"enTitle":"Third History","ruTitle":"Третья история","en":"You and Irene rewrite the grammar of memory. From now on, recovered memories arrive as invitations rather than commands. Citizens may accept, postpone, share, or refuse them. Irene becomes an independent person instead of your missing conscience, while you become the first identity able to change without being erased.","ru":"Вы вместе с Irene переписываете грамматику памяти. Отныне возвращённые воспоминания приходят как приглашения, а не приказы. Жители могут принимать, откладывать, разделять или отклонять их. Irene становится самостоятельной личностью, а не вашей потерянной совестью, а вы — первой личностью, способной изменяться без стирания.","resultEn":"Reform ending · Irene becomes independent · Memory belongs to its experiencer","resultRu":"Финал реформы · Irene становится самостоятельной · Память принадлежит тому, кто её пережил"},"crown":{"enTitle":"The Interpreter of Evervale","ruTitle":"Посредник Эвервейла","en":"You accept the Mirror Crown and merge with the city's living mind. The Nameless Queen regains a name, but not absolute power: you translate the needs of the streets to their inhabitants and the voices of citizens back to the city. Over time, nobody can say whether you rule Evervale or Evervale dreams through you.","ru":"Вы принимаете Зеркальную корону и объединяетесь с живым разумом города. Безымянная Королева возвращает имя, но не абсолютную власть: вы переводите потребности улиц жителям, а голоса жителей — городу. Со временем никто не может сказать, правите ли вы Эвервейлом или Эвервейл видит сны через вас.","resultEn":"Mythic ending · The Queen is transformed · You become part of the city","resultRu":"Мифический финал · Королева меняется · Вы становитесь частью города"},"lyra":{"enTitle":"The Original Life","ruTitle":"Первоначальная жизнь","en":"You return the body to Lyra. Your constructed identity begins to dissolve—but Irene saves your language, Silas saves your emotional continuity, and Oren transfers the remaining pattern into a new body without a predetermined face. Lyra awakens as herself. You awaken as someone without an assigned past, finally free to choose a name.","ru":"Вы возвращаете тело Лире. Ваша сконструированная личность начинает исчезать, но Irene сохраняет ваш язык, Сайлас — эмоциональную непрерывность, а Орен переносит оставшуюся схему в новое тело без заранее определённого лица. Лира просыпается собой. Вы просыпаетесь человеком без назначенного прошлого и впервые можете самостоятельно выбрать имя.","resultEn":"Sacrifice ending · Lyra returns · Your new life begins without a script","resultRu":"Финал жертвы · Лира возвращается · Ваша новая жизнь начинается без сценария"},"silas":{"enTitle":"Two Names at Dawn","ruTitle":"Два имени на рассвете","en":"You refuse to become another mechanism. You and Silas escape through the collapsing lower tunnels while every faction fights for the core. Beyond the city walls, neither of you can fully remember the relationship imposed by the Archive. You decide to meet again as strangers—and discover whether you would choose each other without the memory that once made the choice for you.","ru":"Вы отказываетесь становиться очередным механизмом. Вместе с Сайласом вы уходите через разрушающиеся нижние туннели, пока все стороны сражаются за центр. За городскими стенами ни один из вас полностью не помнит отношения, навязанные Архивом. Вы решаете познакомиться заново и узнать, выбрали бы вы друг друга без памяти, которая раньше делала выбор за вас.","resultEn":"Personal ending · Evervale's fate remains uncertain · Silas relationship route completed","resultRu":"Личный финал · Судьба Эвервейла остаётся неизвестной · Линия отношений с Сайласом завершена"}};
function campaignRouteName(){const names={order:isEnglishLevel(state.level)?'Order route':'Линия порядка',truth:isEnglishLevel(state.level)?'Resistance route':'Линия сопротивления',personal:isEnglishLevel(state.level)?'Secret Archive route':'Линия тайного Архива'};return names[state.route]||''}
function startCampaign(type){state.route=type;state.campaignNode={order:'ministry_start',truth:'truth_start',personal:'personal_start'}[type];state.campaignHistory=[];state.alignment={...initial.alignment};state.bonds={...initial.bonds,silas:Math.max(0,state.trust)};state.secrets=[];save();go('campaign')}
function hasSecret(name){if(name==='irene_origin_or_grammar')return state.secrets.includes('irene_origin')||state.secrets.includes('grammar_key')||state.secrets.includes('third_tense');if(name==='lyra')return state.secrets.some(s=>['lyra_inside','lyra_body','lyra_vessel'].includes(s));return state.secrets.includes(name)}
function choiceAllowed(c){const r=c.requires;if(!r)return true;if(r.align)return (state.alignment[r.align]||0)>=(r.min||0);if(r.bond)return (state.bonds[r.bond]||0)>=(r.min||0);if(r.secret)return hasSecret(r.secret);return true}
function applyCampaignEffects(e){if(!e)return;if(typeof e.stability==='number')state.stability=Math.max(0,Math.min(120,state.stability+e.stability));if(typeof e.influence==='number')state.influence+=e.influence;if(typeof e.trust==='number')state.trust+=e.trust;if(e.align)Object.entries(e.align).forEach(([k,v])=>state.alignment[k]=(state.alignment[k]||0)+v);if(e.bonds)Object.entries(e.bonds).forEach(([k,v])=>state.bonds[k]=(state.bonds[k]||0)+v);if(e.addSecret&&!state.secrets.includes(e.addSecret))state.secrets.push(e.addSecret)}
function renderCampaign(){const n=campaignNodes[state.campaignNode];if(!n){go('ending');return}const b1=isEnglishLevel(state.level),a1=(state.level==='A1'||state.level==='A0');document.getElementById('campaignChapter').textContent=b1?n.chapter:n.chapterRu;document.getElementById('campaignRoute').textContent=campaignRouteName();document.getElementById('campaignKicker').textContent=n.kicker;document.getElementById('campaignTitle').textContent=b1?n.title:n.titleRu;const echoNode=state.campaignNode==='archive_echo';document.getElementById('campaignSpeaker').textContent=echoNode?(state.protagonist==='male'?'Arden Echo':'Elara Echo'):n.speaker;document.getElementById('campaignRole').textContent=b1?n.role:n.roleRu;document.getElementById('campaignQuote').textContent='“'+n.quote+'”';document.getElementById('campaignBody').textContent=n.body;const art=document.getElementById('campaignArt');const artKey=echoNode?(state.protagonist==='male'?'arden':'elara'):n.img;art.className='campaign-art img-'+artKey;const tr=document.getElementById('campaignTranslation');tr.textContent='«'+n.quoteRu+'»\n\n'+n.bodyRu;tr.classList.toggle('hidden',!a1);const vocab=document.getElementById('campaignVocab');vocab.innerHTML=b1?'':(n.vocab||[]).map(v=>'<span>'+v+'</span>').join('');const tools=document.getElementById('campaignTools');tools.innerHTML='';if(state.level==='A2'){const tbtn=document.createElement('button');tbtn.className='tool-btn';tbtn.textContent='Show translation';tbtn.onclick=()=>toggleBox('campaignTranslation');tools.appendChild(tbtn)}const choices=document.getElementById('campaignChoices');choices.innerHTML='';(n.choices||[]).filter(choiceAllowed).forEach((c,i)=>{const btn=document.createElement('button');btn.className='campaign-choice';btn.innerHTML='<small>'+c.tag+'</small>'+c.en+(a1?'<span class="ru">'+c.ru+'</span>':'');btn.onclick=()=>chooseCampaign(c);choices.appendChild(btn)});document.getElementById('campaignStability').textContent=state.stability;document.getElementById('campaignInfluence').textContent=state.influence;document.getElementById('campaignSilas').textContent=state.bonds.silas||0;document.getElementById('campaignIrene').textContent=state.bonds.irene||0;document.getElementById('campaignLength').textContent=b1?'Your choices open different scenes, alliances, hidden revelations, and six possible endings.':'Ваши решения открывают разные сцены, союзы, скрытые откровения и шесть возможных финалов.';updateMusicButtons()}
function chooseCampaign(c){clickSfx();applyCampaignEffects(c.effects);state.campaignHistory.push(state.campaignNode);if(c.ending){completeCampaign(c.ending);return}state.campaignNode=c.next;save();renderCampaign();window.scrollTo(0,0)}
function completeCampaign(key){const e=campaignEndings[key]||campaignEndings.destroy;const b1=isEnglishLevel(state.level);document.getElementById('endingKicker').textContent=b1?'END OF THE LONG CAMPAIGN':'ФИНАЛ БОЛЬШОЙ КАМПАНИИ';document.getElementById('endingTitle').textContent=b1?e.enTitle:e.ruTitle;document.getElementById('endingText').textContent=b1?e.en:e.ru;const route=campaignRouteName();const stats=b1?'Route: '+route+' · Chapters completed: '+state.campaignHistory.length+' · Secrets found: '+state.secrets.length:'Линия: '+route+' · Пройдено сцен: '+state.campaignHistory.length+' · Найдено секретов: '+state.secrets.length;document.getElementById('endingResult').textContent=(b1?e.resultEn:e.resultRu)+'\n'+stats;state.campaignNode=null;save();go('ending')}
